css:
.fxa-graph {
  /* Re-theme with paper, ink and accent; the other package hues are turned from the accent. */
  --fxa-graph-paper: oklch(0.972 0.012 85);
  --fxa-graph-ink: oklch(0.27 0.02 55);
  --fxa-graph-accent: oklch(0.6 0.15 38);
  --fxa-graph-c0: var(--fxa-graph-accent);
  --fxa-graph-c1: oklch(0.56 0.1 140);
  --fxa-graph-c2: oklch(0.52 0.09 250);
  --fxa-graph-c3: oklch(0.72 0.13 78);

  --fxa-graph-muted: color-mix(in oklch, var(--fxa-graph-ink) 62%, var(--fxa-graph-paper));
  --fxa-graph-line: color-mix(in oklch, var(--fxa-graph-ink) 12%, transparent);
  --fxa-graph-chip: color-mix(in oklch, var(--fxa-graph-ink) 4%, var(--fxa-graph-paper));
  --fxa-graph-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-graph-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 0.94;
  min-block-size: 300px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-graph-ink);
  background:
    radial-gradient(circle at 1px 1px, color-mix(in oklch, var(--fxa-graph-ink) 11%, transparent) 0.9px, transparent 1.3px) 0 0 / 14px 14px,
    var(--fxa-graph-paper);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-graph-line);

  @supports (color: oklch(from red l c h)) {
    --fxa-graph-c1: oklch(from var(--fxa-graph-accent) calc(l - 0.04) calc(c * 0.68) calc(h + 102));
    --fxa-graph-c2: oklch(from var(--fxa-graph-accent) calc(l - 0.08) calc(c * 0.6) calc(h + 212));
    --fxa-graph-c3: oklch(from var(--fxa-graph-accent) calc(l + 0.12) calc(c * 0.87) calc(h + 40));
  }

  & .fxa-graph__body {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-areas:
      "head stats"
      "stage stage"
      "legend legend";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto minmax(0, 1fr) auto;
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
  }

  & .fxa-graph__head { grid-area: head; min-inline-size: 0; }
  & .fxa-graph__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-graph-muted);
  }
  & .fxa-graph__title {
    margin: 5px 0 0;
    font-size: clamp(19px, 6.4cqi, 28px);
    font-weight: 750;
    line-height: 1;
    letter-spacing: -0.025em;
    text-wrap: balance;
  }

  & .fxa-graph__stats {
    grid-area: stats;
    display: flex;
    gap: clamp(10px, 3.6cqi, 18px);
    margin: 0;
    align-self: start;
  }
  & .fxa-graph__stat {
    display: grid;
    justify-items: end;
    gap: 3px;
    transition: opacity 0.5s var(--fxa-graph-out), translate 0.7s var(--fxa-graph-spring);
    transition-delay: calc(var(--i) * 60ms + 140ms);
    @starting-style { opacity: 0; translate: 0 6px; }
  }
  & .fxa-graph__stat dt {
    font: 600 9.5px/1 system-ui, sans-serif;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-graph-muted);
  }
  & .fxa-graph__stat dd {
    margin: 0;
    font: 650 clamp(17px, 5.4cqi, 23px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.03em;
  }

  & .fxa-graph__stage {
    grid-area: stage;
    position: relative;
    margin: 4px calc(-1 * clamp(12px, 4cqi, 18px));
    min-block-size: 0;
    outline: none;
    touch-action: pan-y;
    cursor: default;
  }
  & .fxa-graph__stage[data-hover] { cursor: grab; }
  & .fxa-graph__stage[data-drag] { cursor: grabbing; }
  & .fxa-graph__stage:focus-visible {
    border-radius: 12px;
    box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--fxa-graph-accent) 70%, transparent),
      inset 0 0 0 5px color-mix(in oklch, var(--fxa-graph-accent) 12%, transparent);
  }
  & .fxa-graph__cv { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; display: block; }

  & .fxa-graph__tip {
    position: absolute;
    left: 0;
    top: 0;
    display: grid;
    gap: 3px;
    padding: 7px 10px 8px;
    border-radius: 10px;
    pointer-events: none;
    white-space: nowrap;
    background: color-mix(in oklch, var(--fxa-graph-paper) 94%, transparent);
    box-shadow:
      inset 0 0 0 1px var(--fxa-graph-line),
      0 10px 24px -12px color-mix(in oklch, var(--fxa-graph-ink) 45%, transparent);
    opacity: 0;
    scale: 0.94;
    transform-origin: 0 50%;
    transition: opacity 0.16s linear, scale 0.45s var(--fxa-graph-spring);
  }
  & .fxa-graph__tip[data-on] { opacity: 1; scale: 1; }
  & .fxa-graph__tip[data-flip] { transform-origin: 100% 50%; }
  & .fxa-graph__tipname { font: 650 12px/1.15 ui-monospace, Menlo, monospace; letter-spacing: -0.01em; }
  & .fxa-graph__tipmeta {
    display: flex;
    align-items: center;
    gap: 6px;
    font: 600 9.5px/1 system-ui, sans-serif;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-graph-muted);
  }
  & .fxa-graph__tipdot { inline-size: 7px; block-size: 7px; border-radius: 50%; background: var(--c, var(--fxa-graph-c0)); }
  & .fxa-graph__tipdeg {
    display: flex;
    gap: 10px;
    font: 500 11px/1.2 system-ui, sans-serif;
    color: var(--fxa-graph-muted);
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxa-graph-ink); font-weight: 700; }
  }

  & .fxa-graph__legend {
    grid-area: legend;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
  }
  & .fxa-graph__pkg,
  & .fxa-graph__free {
    appearance: none;
    border: 0;
    margin: 0;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-block-size: 28px;
    padding: 0 10px 0 8px;
    border-radius: 999px;
    background: var(--fxa-graph-chip);
    color: var(--fxa-graph-ink);
    font: 600 11.5px/1 system-ui, sans-serif;
    cursor: pointer;
    box-shadow: inset 0 0 0 1px var(--fxa-graph-line);
    transition:
      background-color 0.2s linear,
      box-shadow 0.2s linear,
      color 0.2s linear,
      opacity 0.45s var(--fxa-graph-out),
      translate 0.6s var(--fxa-graph-spring);
    transition-delay: 0s, 0s, 0s, calc(var(--i, 0) * 50ms + 220ms), calc(var(--i, 0) * 50ms + 220ms);
    @starting-style { opacity: 0; translate: 0 8px; }
  }
  & .fxa-graph__pkg em {
    font: 600 10.5px/1 ui-monospace, Menlo, monospace;
    font-style: normal;
    font-variant-numeric: tabular-nums;
    color: var(--fxa-graph-muted);
  }
  & .fxa-graph__sw {
    inline-size: 9px;
    block-size: 9px;
    border-radius: 50%;
    background: var(--c);
    box-shadow: 0 0 0 1.5px var(--c);
    transition: background-color 0.25s var(--fxa-graph-out), scale 0.4s var(--fxa-graph-spring);
  }
  & .fxa-graph__pkg:hover { background: color-mix(in oklch, var(--c) 12%, var(--fxa-graph-chip)); }
  & .fxa-graph__pkg[aria-pressed="false"] {
    color: var(--fxa-graph-muted);
    background: transparent;
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--fxa-graph-ink) 10%, transparent);
    & .fxa-graph__sw { background: transparent; scale: 0.8; }
    & em { opacity: 0.6; }
  }
  & .fxa-graph__free {
    margin-inline-start: auto;
    padding-inline: 8px 11px;
    background: var(--fxa-graph-ink);
    color: var(--fxa-graph-paper);
    box-shadow: none;
    & svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
    & b { font-variant-numeric: tabular-nums; }
  }
  & .fxa-graph__free[hidden] { display: none; }
  & .fxa-graph__free:hover { background: color-mix(in oklch, var(--fxa-graph-ink) 86%, var(--fxa-graph-accent)); }
  & .fxa-graph__pkg:focus-visible,
  & .fxa-graph__free:focus-visible {
    outline: 2px solid var(--fxa-graph-ink);
    outline-offset: 2px;
  }

  & .fxa-graph__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@container (max-width: 330px) {
  .fxa-graph .fxa-graph__pkg { padding-inline: 7px 8px; gap: 5px; }
  .fxa-graph .fxa-graph__pkg em { display: none; }
  .fxa-graph .fxa-graph__stat dt { font-size: 8.5px; }
  .fxa-graph .fxa-graph__long { display: none; }
}

@container (min-width: 600px) {
  .fxa-graph .fxa-graph__body {
    grid-template-areas:
      "head stage"
      "stats stage"
      "legend stage";
    grid-template-columns: minmax(170px, 28%) minmax(0, 1fr);
    grid-template-rows: auto auto 1fr;
    row-gap: 18px;
  }
  .fxa-graph .fxa-graph__stats { justify-self: start; }
  .fxa-graph .fxa-graph__stat { justify-items: start; }
  .fxa-graph .fxa-graph__legend { flex-direction: column; align-items: stretch; align-self: end; }
  .fxa-graph .fxa-graph__pkg em { margin-inline-start: auto; }
  .fxa-graph .fxa-graph__free { margin-inline-start: 0; }
  .fxa-graph .fxa-graph__stage { margin: calc(-1 * clamp(12px, 4cqi, 18px)); margin-inline-start: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .fxa-graph {
    & .fxa-graph__stat,
    & .fxa-graph__pkg,
    & .fxa-graph__free,
    & .fxa-graph__sw,
    & .fxa-graph__tip { transition-duration: 0s; transition-delay: 0s; }
  }
}

js:
/* Module gravity — a force-directed import graph on hand-written physics.
   Every pair of modules repels with an inverse-square force, every import is a
   Hooke spring (shorter inside a package), each package is drawn weakly to its
   own centroid and the whole graph to the middle. All forces scale with a
   cooling temperature (alpha) and are integrated with damped semi-implicit Euler
   at a fixed 60 Hz step. Pulses travel importer -> imported to show direction. */
const stage = root.querySelector('.fxa-graph__stage');
const cv = root.querySelector('.fxa-graph__cv');
const ctx = cv.getContext('2d');
const tip = root.querySelector('.fxa-graph__tip');
const probe = root.querySelector('.fxa-graph__probe');
const live = root.querySelector('.fxa-graph__sr');
const outN = root.querySelector('[data-k="n"]');
const outE = root.querySelector('[data-k="e"]');
const outPins = root.querySelector('[data-k="pins"]');
const chips = [...root.querySelectorAll('.fxa-graph__pkg')];
const freeBtn = root.querySelector('.fxa-graph__free');
const T = (k) => tip.querySelector('[data-t="' + k + '"]');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const PKGS = ['core', 'render', 'cli', 'plugins'];
// [module, package, imports]
const SRC = [
  ['core/graph', 0, ['core/hash', 'core/events']],
  ['core/fs', 0, ['core/path', 'core/log']],
  ['core/hash', 0, []],
  ['core/log', 0, []],
  ['core/config', 0, ['core/fs', 'core/path', 'core/log']],
  ['core/cache', 0, ['core/hash', 'core/fs']],
  ['core/path', 0, []],
  ['core/events', 0, ['core/log']],
  ['render/md', 1, ['render/tpl', 'render/highlight', 'core/log']],
  ['render/html', 1, ['render/tpl', 'render/minify', 'core/graph']],
  ['render/tpl', 1, ['core/fs', 'core/cache', 'core/path']],
  ['render/img', 1, ['core/fs', 'core/hash', 'core/cache']],
  ['render/css', 1, ['render/minify', 'core/fs', 'core/hash']],
  ['render/minify', 1, ['core/log']],
  ['render/highlight', 1, ['core/cache']],
  ['render/toc', 1, ['render/md']],
  ['render/feed', 1, ['render/html', 'core/config']],
  ['cli/main', 2, ['cli/args', 'cli/build', 'cli/serve', 'cli/init', 'core/config', 'core/log']],
  ['cli/args', 2, []],
  ['cli/serve', 2, ['cli/watch', 'cli/build', 'core/events', 'core/log']],
  ['cli/watch', 2, ['core/fs', 'core/events', 'core/graph']],
  ['cli/build', 2, ['core/graph', 'core/config', 'core/cache', 'render/html', 'render/css', 'render/img']],
  ['cli/init', 2, ['core/fs', 'core/config']],
  ['plug/sitemap', 3, ['core/graph', 'core/config']],
  ['plug/i18n', 3, ['render/tpl', 'core/config', 'core/fs']],
  ['plug/search', 3, ['render/md', 'core/graph', 'core/hash']],
  ['plug/og-image', 3, ['render/img', 'render/tpl']],
  ['plug/redirects', 3, ['core/config', 'core/fs']],
  ['plug/drafts', 3, ['core/graph', 'core/events']],
  ['plug/assets', 3, ['render/img', 'render/css', 'core/cache', 'core/hash']],
];

function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = rng(3202);

const nodes = SRC.map(([name, p], i) => ({
  i, name, p, x: 0, y: 0, vx: 0, vy: 0, fx: 0, fy: 0,
  fixed: false, pin: false, on: true, vis: 1, inD: 0, outD: 0, r: 4, m: 1, ph: rand() * 6.283,
}));
const byName = new Map(nodes.map((n) => [n.name, n]));
const edges = [];
for (const [name, , imps] of SRC) {
  for (const t of imps) {
    const a = byName.get(name), b = byName.get(t);
    edges.push({ a, b });
    a.outD++; b.inD++;
  }
}
const nbrs = nodes.map(() => new Set());
for (const e of edges) { nbrs[e.a.i].add(e.b.i); nbrs[e.b.i].add(e.a.i); }
for (const n of nodes) n.m = 1 + n.inD * 0.09;
// one labelled representative per package: its most depended-on module
const heads = PKGS.map((_, p) => nodes.filter((n) => n.p === p)
  .sort((a, b) => (b.inD * 3 + b.outD) - (a.inD * 3 + a.outD))[0]);

/* ── colour: resolve the CSS custom properties (oklch, color-mix) to sRGB ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const rgba = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a.toFixed(3) + ')';
let pal = null;
function theme() {
  pal = {
    paper: rgb('--fxa-graph-paper'),
    ink: rgb('--fxa-graph-ink'),
    pk: [0, 1, 2, 3].map((i) => rgb('--fxa-graph-c' + i)),
  };
}

/* ── geometry ── */
let W = 0, H = 0, S = 1, dpr = 1;
const SEEDS = [[0.5, 0.5], [0.78, 0.4], [0.22, 0.3], [0.3, 0.76]];
function seed(spread) {
  for (const n of nodes) {
    const s = SEEDS[n.p];
    n.x = W * (0.5 + (s[0] - 0.5) * spread) + (rand() - 0.5) * W * 0.14 * spread;
    n.y = H * (0.5 + (s[1] - 0.5) * spread) + (rand() - 0.5) * H * 0.14 * spread;
    n.vx = n.vy = 0;
  }
}
function sizeNodes() {
  const base = Math.max(3.2, Math.min(4.8, S / 72));
  for (const n of nodes) n.r = base * (1 + Math.sqrt(n.inD) * 0.5);
}
function resize() {
  const r = stage.getBoundingClientRect();
  const w = Math.max(40, Math.round(r.width)), h = Math.max(40, Math.round(r.height));
  if (w === W && h === H) return false;
  const first = !W;
  if (!first) for (const n of nodes) { n.x *= w / W; n.y *= h / H; n.fx *= w / W; n.fy *= h / H; }
  W = w; H = h; S = Math.sqrt(W * H);
  dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr);
  cv.height = Math.round(H * dpr);
  sizeNodes();
  if (first) {
    if (calm) { seed(1); alpha = 1; for (let k = 0; k < 360; k++) { tick(); alpha *= 0.985; } alpha = 0; }
    else { seed(0.12); alpha = 1; }
  }
  return true;
}

/* ── physics ── */
let alpha = 1, alphaTarget = 0, t = 0;
function tick() {
  const A = alpha;
  const K = (S * 0.088) * (S * 0.088);
  const n = nodes.length;
  for (let i = 0; i < n; i++) {
    const a = nodes[i];
    if (!a.on) continue;
    for (let j = i + 1; j < n; j++) {
      const b = nodes[j];
      if (!b.on) continue;
      let dx = b.x - a.x, dy = b.y - a.y;
      let d2 = dx * dx + dy * dy;
      if (d2 < 1) { dx = (rand() - 0.5); dy = (rand() - 0.5); d2 = 1; }
      const d = Math.sqrt(d2);
      const f = (K * A * a.m * b.m) / (d2 * d);
      const fx = dx * f, fy = dy * f;
      a.vx -= fx / a.m; a.vy -= fy / a.m;
      b.vx += fx / b.m; b.vy += fy / b.m;
    }
  }
  for (const e of edges) {
    const a = e.a, b = e.b;
    if (!a.on || !b.on) continue;
    const dx = b.x - a.x, dy = b.y - a.y;
    const d = Math.sqrt(dx * dx + dy * dy) || 1;
    const L = S * (a.p === b.p ? 0.09 : 0.2) + a.r + b.r;
    const f = (0.05 * A * (d - L)) / d;
    a.vx += dx * f; a.vy += dy * f;
    b.vx -= dx * f; b.vy -= dy * f;
  }
  const gx = 0.0026 * Math.min(1, H / W), gy = 0.006 * Math.min(1, W / H);
  const life = calm ? 0 : 1;
  for (const a of nodes) {
    if (!a.on) continue;
    // each package drifts toward its own quarter of the stage, the graph toward the middle
    a.vx += (SEEDS[a.p][0] * W - a.x) * 0.009 * A + (W / 2 - a.x) * gx * A;
    a.vy += (SEEDS[a.p][1] * H - a.y) * 0.009 * A + (H / 2 - a.y) * gy * A;
    // a slow wander keeps the graph breathing at rest
    a.vx += Math.sin(t * 0.55 + a.ph) * 0.018 * life;
    a.vy += Math.cos(t * 0.43 + a.ph * 1.7) * 0.018 * life;
    a.vx *= 0.8; a.vy *= 0.8;
    const sp = Math.hypot(a.vx, a.vy);
    if (sp > 14) { a.vx *= 14 / sp; a.vy *= 14 / sp; }
    if (a.fixed) { a.x = a.fx; a.y = a.fy; a.vx = a.vy = 0; continue; }
    a.x += a.vx; a.y += a.vy;
    const pad = a.r + 6;
    if (a.x < pad) { a.x = pad; a.vx *= -0.3; } else if (a.x > W - pad) { a.x = W - pad; a.vx *= -0.3; }
    if (a.y < pad) { a.y = pad; a.vy *= -0.3; } else if (a.y > H - pad) { a.y = H - pad; a.vy *= -0.3; }
  }
}

/* ── pulses: importer -> imported ── */
const pulses = [];
let pulseClock = 0;
function spawnPulse() {
  const f = focus();
  let pool = edges;
  if (f && rand() < 0.65) pool = edges.filter((e) => e.a === f || e.b === f);
  const e = pool[Math.floor(rand() * pool.length)];
  if (!e || !e.a.on || !e.b.on) return;
  pulses.push({ e, t: 0, sp: 0.8 + rand() * 0.5 });
}
function bend(e) {
  const ax = e.a.x, ay = e.a.y, bx = e.b.x, by = e.b.y;
  return [(ax + bx) / 2 - (by - ay) * 0.13, (ay + by) / 2 + (bx - ax) * 0.13];
}

/* ── state ── */
let hover = null, sel = null, drag = null, focused = false;
const focus = () => (drag && drag.n) || hover || sel;

/* ── draw ── */
function draw() {
  if (!pal || !W) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  const f = focus();
  const hot = f ? nbrs[f.i] : null;
  ctx.lineCap = 'round';

  for (const e of edges) {
    const v = Math.min(e.a.vis, e.b.vis);
    if (v < 0.01) continue;
    const lit = f && (e.a === f || e.b === f);
    const [mx, my] = bend(e);
    ctx.beginPath();
    ctx.moveTo(e.a.x, e.a.y);
    ctx.quadraticCurveTo(mx, my, e.b.x, e.b.y);
    if (lit) {
      ctx.strokeStyle = rgba(pal.pk[e.a.p], 0.9 * v);
      ctx.lineWidth = 1.6;
    } else {
      ctx.strokeStyle = rgba(pal.ink, (f ? 0.06 : 0.17) * v);
      ctx.lineWidth = 1;
    }
    ctx.stroke();
  }

  for (const p of pulses) {
    const e = p.e;
    const v = Math.min(e.a.vis, e.b.vis);
    if (v < 0.05) continue;
    const [mx, my] = bend(e);
    const u = p.t, w = 1 - u;
    const x = w * w * e.a.x + 2 * w * u * mx + u * u * e.b.x;
    const y = w * w * e.a.y + 2 * w * u * my + u * u * e.b.y;
    const lit = !f || e.a === f || e.b === f;
    ctx.fillStyle = rgba(pal.pk[e.a.p], Math.sin(Math.PI * u) * v * (lit ? 0.95 : 0.15));
    ctx.beginPath();
    ctx.arc(x, y, lit && f ? 2.2 : 1.7, 0, 6.283);
    ctx.fill();
  }

  for (const n of nodes) {
    if (n.vis < 0.01) continue;
    const dim = f && n !== f && !hot.has(n.i);
    const a = n.vis * (dim ? 0.2 : 1);
    const r = n.r * (0.6 + 0.4 * n.vis);
    if (n === f) {
      ctx.fillStyle = rgba(pal.pk[n.p], 0.16);
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 9, 0, 6.283); ctx.fill();
    }
    ctx.beginPath();
    ctx.arc(n.x, n.y, r, 0, 6.283);
    ctx.fillStyle = rgba(pal.pk[n.p], a);
    ctx.fill();
    ctx.lineWidth = 1.6;
    ctx.strokeStyle = rgba(pal.paper, a);
    ctx.stroke();
    if (n.pin) {
      ctx.setLineDash([2, 2.4]);
      ctx.lineWidth = 1.2;
      ctx.strokeStyle = rgba(pal.ink, 0.75 * a);
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 3.5, 0, 6.283); ctx.stroke();
      ctx.setLineDash([]);
    }
    if (n === sel && focused) {
      ctx.lineWidth = 1.6;
      ctx.strokeStyle = rgba(pal.ink, 0.9);
      ctx.beginPath(); ctx.arc(n.x, n.y, r + (n.pin ? 6.5 : 4), 0, 6.283); ctx.stroke();
    }
  }

  // labels: one per package at rest, the neighbourhood when something is in focus
  ctx.font = '600 10.5px ui-monospace, Menlo, monospace';
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';
  const lab = f ? [...hot].map((i) => nodes[i]).filter((n) => n.on) : heads.filter((n) => n.on);
  for (const n of lab) {
    if (n.vis < 0.3) continue;
    const txt = n.name;
    const tw = ctx.measureText(txt).width;
    const right = n.x + n.r + 6 + tw < W - 6;
    const x = right ? n.x + n.r + 5 : n.x - n.r - 5 - tw;
    ctx.lineWidth = 3.5;
    ctx.strokeStyle = rgba(pal.paper, 0.92 * n.vis);
    ctx.strokeText(txt, x, n.y);
    ctx.fillStyle = f ? rgba(pal.ink, 0.86 * n.vis) : rgba(pal.pk[n.p], n.vis);
    ctx.fillText(txt, x, n.y);
  }
}

/* ── tip and announcements ── */
let tipFor = null, tipW = 0, tipH = 0;
function fillTip(n) {
  T('name').textContent = n.name;
  T('pkg').textContent = PKGS[n.p];
  T('pin').textContent = n.pin ? '· pinned' : '';
  T('in').textContent = n.inD;
  T('out').textContent = n.outD;
  tip.style.setProperty('--c', 'var(--fxa-graph-c' + n.p + ')');
  tipW = tip.offsetWidth; tipH = tip.offsetHeight;
}
function placeTip() {
  const f = focus();
  const show = f && f.vis > 0.5 && !(drag && drag.moved);
  if (!show) { if (tipFor) { tip.removeAttribute('data-on'); tipFor = null; } return; }
  if (f !== tipFor || tip.dataset.pin !== String(f.pin)) { fillTip(f); tip.dataset.pin = String(f.pin); }
  tipFor = f;
  const gap = f.r + 12;
  let x = f.x + gap, flip = false;
  if (x + tipW > W - 8) { x = f.x - gap - tipW; flip = true; }
  const y = Math.max(6, Math.min(H - tipH - 6, f.y - tipH / 2));
  tip.style.translate = Math.round(x) + 'px ' + Math.round(y) + 'px';
  tip.toggleAttribute('data-flip', flip);
  tip.setAttribute('data-on', '');
}
function say(n) {
  if (!n) { live.textContent = 'Selection cleared.'; return; }
  live.textContent = n.name + ', ' + PKGS[n.p] + ' package. Imported by ' + n.inD +
    (n.inD === 1 ? ' module' : ' modules') + ', imports ' + n.outD + '.' + (n.pin ? ' Pinned.' : '');
}
function setSel(n, announce = true) {
  sel = n;
  if (announce) say(n);
  kick();
}
function counts() {
  let nv = 0, ev = 0, pins = 0;
  for (const n of nodes) { if (n.on) nv++; if (n.pin && n.on) pins++; }
  for (const e of edges) if (e.a.on && e.b.on) ev++;
  outN.textContent = nv;
  outE.textContent = ev;
  outPins.textContent = pins + (pins === 1 ? ' pin' : ' pins');
  freeBtn.hidden = pins === 0;
}
function setPin(n, on) {
  n.pin = on;
  n.fixed = on;
  if (on) { n.fx = n.x; n.fy = n.y; }
  alpha = Math.max(alpha, 0.25);
  counts();
}

/* ── loop ── */
let raf = 0, last = 0, acc = 0, seen = true;
function kick() {
  if (!raf && seen && !document.hidden && root.isConnected) raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
  last = now;
  t += dt;
  let fading = false;
  for (const n of nodes) {
    const goal = n.on ? 1 : 0;
    if (n.vis !== goal) {
      n.vis += (goal - n.vis) * Math.min(1, dt * (calm ? 30 : 7));
      if (Math.abs(goal - n.vis) < 0.01) n.vis = goal; else fading = true;
    }
  }
  alphaTarget = drag ? 0.3 : (calm ? 0 : 0.03);
  acc += dt;
  let steps = 0;
  while (acc >= 1 / 60 && steps < 3) {
    alpha += (alphaTarget - alpha) * (calm ? 0.08 : 0.018);
    tick();
    acc -= 1 / 60; steps++;
  }
  if (steps === 3) acc = 0;
  if (!calm) {
    pulseClock += dt;
    while (pulseClock > 0.13) { pulseClock -= 0.13; if (pulses.length < 36) spawnPulse(); }
    for (let k = pulses.length - 1; k >= 0; k--) {
      pulses[k].t += dt * pulses[k].sp;
      if (pulses[k].t >= 1) pulses.splice(k, 1);
    }
  }
  draw();
  placeTip();
  if (!calm || drag || alpha > 0.004 || fading) kick();
  else last = 0;
}

/* ── pointer ── */
function local(e) {
  const r = stage.getBoundingClientRect();
  return { x: e.clientX - r.left, y: e.clientY - r.top };
}
function hit(p, slop) {
  let best = null, bd = Infinity;
  for (const n of nodes) {
    if (!n.on || n.vis < 0.5) continue;
    const d = Math.hypot(n.x - p.x, n.y - p.y) - n.r;
    if (d < slop && d < bd) { bd = d; best = n; }
  }
  return best;
}
stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const p = local(e);
  const n = hit(p, e.pointerType === 'touch' ? 14 : 7);
  stage.focus({ preventScroll: true });
  if (!n) { if (sel) setSel(null); return; }
  drag = { n, id: e.pointerId, moved: false, x0: p.x, y0: p.y, ox: n.x - p.x, oy: n.y - p.y, wasPinned: n.pin };
  n.fixed = true; n.fx = n.x; n.fy = n.y;
  stage.setPointerCapture(e.pointerId);
  stage.setAttribute('data-drag', '');
  setSel(n);
});
stage.addEventListener('pointermove', (e) => {
  const p = local(e);
  if (drag && e.pointerId === drag.id) {
    if (!drag.moved && Math.hypot(p.x - drag.x0, p.y - drag.y0) > 4) drag.moved = true;
    if (drag.moved) {
      drag.n.fx = Math.max(drag.n.r + 4, Math.min(W - drag.n.r - 4, p.x + drag.ox));
      drag.n.fy = Math.max(drag.n.r + 4, Math.min(H - drag.n.r - 4, p.y + drag.oy));
    }
    kick();
    return;
  }
  if (e.pointerType === 'touch') return;
  const n = hit(p, 7);
  if (n !== hover) {
    hover = n;
    stage.toggleAttribute('data-hover', !!n);
    kick();
  }
});
function release(e) {
  if (!drag || e.pointerId !== drag.id) return;
  const n = drag.n;
  if (drag.moved) setPin(n, true);
  else n.fixed = n.pin;
  drag = null;
  stage.removeAttribute('data-drag');
  say(n);
  kick();
}
stage.addEventListener('pointerup', release);
stage.addEventListener('pointercancel', release);
stage.addEventListener('pointerleave', () => {
  if (hover) { hover = null; stage.removeAttribute('data-hover'); kick(); }
});
stage.addEventListener('dblclick', (e) => {
  const n = hit(local(e), 8);
  if (n && n.pin) { setPin(n, false); say(n); kick(); }
});

/* ── keyboard: spatial navigation between modules ── */
function biggest() {
  return nodes.filter((n) => n.on).sort((a, b) => b.inD - a.inD)[0];
}
function nav(dx, dy) {
  if (!sel || !sel.on) { setSel(biggest()); return; }
  let best = null, bs = Infinity;
  for (const n of nodes) {
    if (n === sel || !n.on) continue;
    const ox = n.x - sel.x, oy = n.y - sel.y;
    const along = ox * dx + oy * dy;
    if (along <= 2) continue;
    const across = Math.abs(ox * dy - oy * dx);
    const score = along + across * 2.2;
    if (score < bs) { bs = score; best = n; }
  }
  if (best) setSel(best);
}
stage.addEventListener('keydown', (e) => {
  const k = e.key;
  if (k === 'ArrowRight') nav(1, 0);
  else if (k === 'ArrowLeft') nav(-1, 0);
  else if (k === 'ArrowUp') nav(0, -1);
  else if (k === 'ArrowDown') nav(0, 1);
  else if (k === 'Home') setSel(biggest());
  else if (k === 'Enter' || k === ' ') {
    if (!sel) setSel(biggest());
    else { setPin(sel, !sel.pin); say(sel); }
  } else if (k === 'Escape') {
    if (!sel) return;
    setSel(null);
  } else return;
  e.preventDefault();
});
stage.addEventListener('focus', () => { focused = true; kick(); });
stage.addEventListener('blur', () => { focused = false; kick(); });

/* ── packages ── */
chips.forEach((b, idx) => {
  b.addEventListener('click', () => {
    const p = +b.dataset.p;
    const on = b.getAttribute('aria-pressed') !== 'true';
    if (!on && chips.filter((c) => c.getAttribute('aria-pressed') === 'true').length === 1) {
      b.animate([{ translate: '0 0' }, { translate: '-3px 0' }, { translate: '3px 0' }, { translate: '0 0' }],
        { duration: calm ? 1 : 260, easing: 'cubic-bezier(.3,.7,.4,1)' });
      return;
    }
    b.setAttribute('aria-pressed', String(on));
    for (const n of nodes) {
      if (n.p !== p) continue;
      n.on = on;
      if (on) {
        // come back in near the package's neighbours, not where they left
        n.x = W / 2 + (n.x - W / 2) * 0.6; n.y = H / 2 + (n.y - H / 2) * 0.6;
      } else if (n === sel) sel = null;
    }
    if (hover && !hover.on) hover = null;
    alpha = Math.max(alpha, 0.6);
    counts();
    live.textContent = PKGS[p] + (on ? ' shown. ' : ' hidden. ') + outN.textContent + ' modules, ' + outE.textContent + ' imports.';
    kick();
  });
  b.addEventListener('keydown', (e) => {
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    e.preventDefault();
    chips[(idx + (e.key === 'ArrowRight' ? 1 : chips.length - 1)) % chips.length].focus();
  });
});
freeBtn.addEventListener('click', () => {
  for (const n of nodes) if (n.pin) { n.pin = false; n.fixed = false; }
  alpha = Math.max(alpha, 0.5);
  counts();
  live.textContent = 'All modules released.';
  stage.focus({ preventScroll: true });
  kick();
});

/* ── lifecycle ── */
function onVis() {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) { last = 0; kick(); }
}
document.addEventListener('visibilitychange', onVis);
function onMotion() {
  if (!root.isConnected) { mq.removeEventListener('change', onMotion); return; }
  calm = mq.matches;
  if (calm) pulses.length = 0;
  kick();
}
mq.addEventListener('change', onMotion);

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  theme();
  if (resize()) { draw(); kick(); }
});
ro.observe(stage);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  seen = entries[entries.length - 1].isIntersecting;
  if (seen) { last = 0; kick(); }
});
io.observe(root);

theme();
resize();
counts();
draw();
kick();

css:
.fxa-globe {
  /* Re-theme with these four; ocean, text, rules and tints are mixed from them. */
  --fxa-globe-night: oklch(0.17 0.014 62);
  --fxa-globe-land: oklch(0.86 0.035 82);
  --fxa-globe-route: oklch(0.8 0.145 70);
  --fxa-globe-hot: oklch(0.71 0.17 38);

  --fxa-globe-ocean: color-mix(in oklch, var(--fxa-globe-night) 86%, var(--fxa-globe-land));
  --fxa-globe-text: color-mix(in oklch, var(--fxa-globe-land) 90%, oklch(1 0 0));
  --fxa-globe-muted: color-mix(in oklch, var(--fxa-globe-land) 58%, var(--fxa-globe-night));
  --fxa-globe-line: color-mix(in oklch, var(--fxa-globe-land) 16%, transparent);
  --fxa-globe-scrim: color-mix(in oklch, var(--fxa-globe-night) 78%, transparent);
  --fxa-globe-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-globe-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 0.96;
  min-block-size: 320px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-globe-text);
  background:
    radial-gradient(90% 70% at 50% 58%, color-mix(in oklch, var(--fxa-globe-night) 88%, var(--fxa-globe-route)) 0%, transparent 70%),
    var(--fxa-globe-night);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-globe-line);

  & .fxa-globe__cv,
  & .fxa-globe__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxa-globe__cv { display: block; }
  & .fxa-globe__stage {
    z-index: 1;
    outline: none;
    cursor: grab;
    touch-action: pan-y;
    border-radius: inherit;
  }
  & .fxa-globe__stage[data-hub] { cursor: pointer; }
  & .fxa-globe__stage[data-drag] { cursor: grabbing; }
  & .fxa-globe__stage:focus-visible {
    box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--fxa-globe-route) 80%, transparent);
  }

  & .fxa-globe__body {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-areas:
      "head stats"
      ". ."
      "readout readout"
      "hubs hubs";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto 1fr auto auto;
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
    pointer-events: none;
    background:
      linear-gradient(to top, var(--fxa-globe-scrim) 0, transparent 34%),
      linear-gradient(to bottom, color-mix(in oklch, var(--fxa-globe-night) 55%, transparent) 0, transparent 22%);
  }

  & .fxa-globe__head { grid-area: head; min-inline-size: 0; }
  & .fxa-globe__eyebrow {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-globe-muted);
    & svg { flex: none; inline-size: 14px; block-size: 14px; fill: none; stroke: var(--fxa-globe-route); stroke-width: 1.3; stroke-linejoin: round; stroke-linecap: round; }
  }
  & .fxa-globe__title {
    margin: 6px 0 0;
    font-size: clamp(19px, 6.2cqi, 28px);
    font-weight: 300;
    line-height: 1;
    letter-spacing: -0.02em;
    text-wrap: balance;
    & span {
      font-weight: 700;
      color: var(--fxa-globe-route);
      font-variant-numeric: tabular-nums;
    }
  }

  & .fxa-globe__stats { grid-area: stats; display: flex; gap: 14px; margin: 0; align-self: start; }
  & .fxa-globe__stat {
    display: grid;
    justify-items: end;
    gap: 3px;
    transition: opacity 0.5s var(--fxa-globe-out), translate 0.7s var(--fxa-globe-spring);
    transition-delay: calc(var(--i) * 60ms + 160ms);
    @starting-style { opacity: 0; translate: 0 -6px; }
  }
  & .fxa-globe__stat dt {
    font: 600 9.5px/1 system-ui, sans-serif;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-globe-muted);
  }
  & .fxa-globe__stat dd {
    margin: 0;
    font: 600 clamp(16px, 5cqi, 21px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  & .fxa-globe__readout {
    grid-area: readout;
    display: grid;
    gap: 4px;
    margin-block-end: 10px;
    min-block-size: 38px;
    align-content: end;
  }
  & .fxa-globe__rcode {
    margin: 0;
    display: flex;
    align-items: baseline;
    gap: 8px;
    font: 700 clamp(18px, 5.6cqi, 24px)/1 ui-monospace, Menlo, monospace;
    letter-spacing: 0.02em;
    color: var(--fxa-globe-route);
    & small { font: 500 12.5px/1 system-ui, sans-serif; letter-spacing: 0; color: var(--fxa-globe-text); }
    &:empty { display: none; }
  }
  & .fxa-globe__rline {
    margin: 0;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 4px 10px;
    font: 500 11.5px/1.3 system-ui, sans-serif;
    color: var(--fxa-globe-muted);
    font-variant-numeric: tabular-nums;
    text-wrap: pretty;
    & svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
    & b { color: var(--fxa-globe-text); font-weight: 650; }
  }
  & .fxa-globe__readout[data-on] .fxa-globe__rline svg { display: none; }

  & .fxa-globe__hubs {
    grid-area: hubs;
    display: flex;
    gap: 5px;
    margin-inline: calc(-1 * clamp(12px, 4cqi, 18px));
    padding-inline: clamp(12px, 4cqi, 18px);
    padding-block: 2px;
    overflow-x: auto;
    scroll-snap-type: x proximity;
    scroll-padding-inline: clamp(12px, 4cqi, 18px);
    scrollbar-width: none;
    pointer-events: auto;
    mask-image: linear-gradient(to right, transparent 0, #000 12px, #000 calc(100% - 22px), transparent);
    &::-webkit-scrollbar { display: none; }
  }
  & .fxa-globe__hub {
    appearance: none;
    flex: none;
    margin: 0;
    border: 0;
    scroll-snap-align: start;
    display: inline-grid;
    place-items: center;
    min-inline-size: 44px;
    block-size: 28px;
    padding: 0 9px;
    border-radius: 8px;
    font: 650 11px/1 ui-monospace, Menlo, monospace;
    letter-spacing: 0.04em;
    color: var(--fxa-globe-text);
    background: color-mix(in oklch, var(--fxa-globe-night) 70%, transparent);
    box-shadow: inset 0 0 0 1px var(--fxa-globe-line);
    cursor: pointer;
    transition:
      background-color 0.2s linear,
      color 0.2s linear,
      box-shadow 0.2s linear,
      opacity 0.4s var(--fxa-globe-out),
      translate 0.6s var(--fxa-globe-spring);
    transition-delay: 0s, 0s, 0s, calc(var(--i) * 28ms + 260ms), calc(var(--i) * 28ms + 260ms);
    @starting-style { opacity: 0; translate: 0 10px; }
  }
  & .fxa-globe__hub:hover { background: color-mix(in oklch, var(--fxa-globe-route) 18%, var(--fxa-globe-night)); }
  & .fxa-globe__hub[aria-pressed="true"] {
    background: var(--fxa-globe-route);
    color: var(--fxa-globe-night);
    box-shadow: none;
  }
  & .fxa-globe__hub:focus-visible { outline: 2px solid var(--fxa-globe-route); outline-offset: 2px; }
}

@container (max-width: 330px) {
  .fxa-globe .fxa-globe__stats { display: none; }
}
@container (min-width: 620px) {
  .fxa-globe .fxa-globe__body {
    grid-template-areas:
      "head stats"
      "readout ."
      ". ."
      "hubs hubs";
    grid-template-rows: auto auto 1fr auto;
  }
  .fxa-globe .fxa-globe__readout { margin-block: 18px 0; max-inline-size: 30ch; }
}

@media (prefers-reduced-motion: reduce) {
  .fxa-globe {
    & .fxa-globe__stat,
    & .fxa-globe__hub { transition-duration: 0s; transition-delay: 0s; }
  }
}

.fxa-stream {
  /* Re-theme with paper, ink, and the shared lightness and chroma of the genre inks. */
  --fxa-stream-paper: oklch(0.966 0.014 88);
  --fxa-stream-ink: oklch(0.25 0.02 60);
  --fxa-stream-l: 0.6;
  --fxa-stream-c: 0.11;

  --fxa-stream-g0: oklch(calc(var(--fxa-stream-l) + 0.08) calc(var(--fxa-stream-c) * 0.7) 75);
  --fxa-stream-g1: oklch(calc(var(--fxa-stream-l) - 0.12) calc(var(--fxa-stream-c) * 0.95) 258);
  --fxa-stream-g2: oklch(calc(var(--fxa-stream-l) - 0.07) calc(var(--fxa-stream-c) * 0.95) 348);
  --fxa-stream-g3: oklch(calc(var(--fxa-stream-l) + 0.08) calc(var(--fxa-stream-c) * 1.55) 33);
  --fxa-stream-g4: oklch(calc(var(--fxa-stream-l) + 0.2) calc(var(--fxa-stream-c) * 1.3) 90);
  --fxa-stream-g5: oklch(calc(var(--fxa-stream-l) + 0.03) calc(var(--fxa-stream-c) * 0.75) 198);
  --fxa-stream-g6: oklch(calc(var(--fxa-stream-l) - 0.13) calc(var(--fxa-stream-c) * 0.9) 155);

  --fxa-stream-muted: color-mix(in oklch, var(--fxa-stream-ink) 60%, var(--fxa-stream-paper));
  --fxa-stream-line: color-mix(in oklch, var(--fxa-stream-ink) 13%, transparent);
  --fxa-stream-chip: color-mix(in oklch, var(--fxa-stream-ink) 6%, var(--fxa-stream-paper));
  --fxa-stream-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-stream-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 0.98;
  min-block-size: 330px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-stream-ink);
  background: var(--fxa-stream-paper);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-stream-line);

  & .fxa-stream__body {
    position: absolute;
