  & .fxa-stream__svg:has(.fxa-stream__layer.is-on) .fxa-stream__labels text:not(.is-on) { opacity: 0.25; }

  & .fxa-stream__months text {
    font: 600 9px/1 ui-monospace, Menlo, monospace;
    letter-spacing: 0.06em;
    fill: var(--fxa-stream-muted);
  }
  & .fxa-stream__months line { stroke: var(--fxa-stream-line); stroke-width: 1; }

  & .fxa-stream__notes {
    & text {
