    align-items: end;
    row-gap: 6px;
  }
  & .fxa-stream__week {
    grid-area: week;
    margin: 0;
    font: 500 11.5px/1.2 system-ui, sans-serif;
    color: var(--fxa-stream-muted);
    & b { font: 700 11.5px/1 ui-monospace, Menlo, monospace; color: var(--fxa-stream-ink); margin-inline-end: 4px; }
  }
  & .fxa-stream__total {
    grid-area: total;
    margin: 0;
    display: flex;
    align-items: baseline;
    gap: 5px;
    font: 650 clamp(18px, 5.6cqi, 23px)/1 ui-monospace, Menlo, monospace;
    letter-spacing: -0.03em;
    font-variant-numeric: tabular-nums;
    & small { font: 600 9.5px/1 system-ui, sans-serif; letter-spacing: 0.08em; text-transform: uppercase; color: var(--fxa-stream-muted); }
  }
  & .fxa-stream__bar {
    grid-area: bar;
    display: flex;
    gap: 2px;
    block-size: 8px;
    & span {
      flex: var(--v) 1 0;
      min-inline-size: 0;
      border-radius: 2px;
      background: var(--c);
      transition: flex-grow 0.5s var(--fxa-stream-out), opacity 0.25s linear, scale 0.35s var(--fxa-stream-spring);
      transform-origin: 50% 100%;
    }
    &:has(.is-on) span:not(.is-on) { opacity: 0.3; }
    & span.is-on { scale: 1 1.6; }
  }
  & .fxa-stream__genre {
    grid-area: genre;
    margin: 0;
    display: flex;
    align-items: center;
    gap: 7px;
    min-block-size: 16px;
    font: 500 11.5px/1.2 system-ui, sans-serif;
    color: var(--fxa-stream-muted);
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxa-stream-ink); font-weight: 700; }
  }
  & .fxa-stream__sw { inline-size: 10px; block-size: 10px; border-radius: 3px; background: var(--c, var(--fxa-stream-ink)); }
}

@container (max-width: 340px) {
  .fxa-stream .fxa-stream__body {
    grid-template-areas:
      "head head"
      "switch switch"
      "chart chart"
      "read read";
    grid-template-rows: auto auto minmax(0, 1fr) auto;
  }
  .fxa-stream .fxa-stream__switch { margin-block-start: 10px; justify-self: start; }
  .fxa-stream .fxa-stream__note--minor { display: none; }
}
@container (min-width: 620px) {
  .fxa-stream .fxa-stream__body {
    grid-template-areas:
      "head read"
      "switch read"
      "chart chart";
    grid-template-columns: minmax(0, 1fr) minmax(260px, 42%);
    grid-template-rows: auto auto minmax(0, 1fr);
    column-gap: 28px;
  }
  .fxa-stream .fxa-stream__switch { justify-self: start; margin-block-start: 12px; }
  .fxa-stream .fxa-stream__read { align-self: start; }
}

@media (prefers-reduced-motion: reduce) {
  .fxa-stream {
    & .fxa-stream__layers,
    & .fxa-stream__play,
