    & .fxa-stream__bar span,
    & .fxa-stream__switch::before { transition: none; }
  }
}

js:
/* A year on air — a streamgraph with three baselines.
   Layers are ordered inside-out (earliest peaks in the middle) and stacked on
   one of three offsets: Byron & Wattenberg's wiggle, which minimises the
   weighted slope of every layer; a plain zero baseline; and 100% share.
   Changing layout tweens every vertex with a damped spring, layer by layer.
   Curves are Catmull-Rom splines turned into cubic Beziers. */
const NS = 'http://www.w3.org/2000/svg';
const svg = root.querySelector('.fxa-stream__svg');
const gL = root.querySelector('.fxa-stream__layers');
const gLab = root.querySelector('.fxa-stream__labels');
const gM = root.querySelector('.fxa-stream__months');
const gN = root.querySelector('.fxa-stream__notes');
const play = root.querySelector('.fxa-stream__play');
const rule = root.querySelector('.fxa-stream__rule');
const dot = root.querySelector('.fxa-stream__dot');
const bar = root.querySelector('.fxa-stream__bar');
const radios = [...root.querySelectorAll('.fxa-stream__switch [role="radio"]')];
const R = (k) => root.querySelector('[data-r="' + k + '"]');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

/* ── data: weekly listening hours by genre, invented station ── */
const GEN = ['Folk', 'Jazz', 'Classical', 'Electronic', 'Hip-hop', 'Indie', 'Seasonal'];
const DARK_TEXT = [true, false, false, false, true, false, false];
const M = 52;
const gauss = (w, mu, sg) => Math.exp(-((w - mu) * (w - mu)) / (2 * sg * sg));
let seed = 1994;
const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
const SHAPE = [
  (w) => 1800 + 2600 * gauss(w, 41, 4) + 250 * Math.sin((w / 52) * Math.PI * 4),
  (w) => 1900 + 5200 * gauss(w, 26, 1) + 700 * gauss(w, 45, 3),
  (w) => 2600 + 1700 * Math.cos((2 * Math.PI * w) / 52) + 2400 * gauss(w, 0, 1.2) + 900 * gauss(w, 51, 1.5),
  (w) => 1100 + 6200 * gauss(w, 30, 4.5) + 900 * gauss(w, 17, 1.6),
  (w) => 1200 + 2600 * (w / 51) + 400 * Math.sin(w * 0.7),
  (w) => 2800 + 1600 * gauss(w, 15, 4) + 900 * gauss(w, 37, 3),
  (w) => 60 + 7200 * Math.pow(Math.max(0, (w - 45) / 6), 2.4),
];
const V = SHAPE.map((fn) => {
  const a = [];
  for (let w = 0; w < M; w++) a.push(Math.round((fn(w) * (1 + (rnd() - 0.5) * 0.1)) / 10) * 10);
  return a;
});
const TOT = [];
for (let w = 0; w < M; w++) { let s = 0; for (const v of V) s += v[w]; TOT.push(s); }
const NOTES = [
  { g: 1, w: 26, text: 'Harbour Jazz Week', side: -1 },
  { g: 3, w: 32, text: 'Festival summer', side: 1, minor: true },
  { g: 6, w: 50, text: 'Advent', side: -1 },
];

// inside-out order: by week of peak, alternately packed onto the lighter side
const order = (() => {
  const peak = V.map((v) => v.indexOf(Math.max(...v)));
  const sums = V.map((v) => v.reduce((a, b) => a + b, 0));
  const idx = GEN.map((_, i) => i).sort((a, b) => peak[a] - peak[b]);
  const top = [], bottom = [];
  let st = 0, sb = 0;
  for (const i of idx) { if (st < sb) { top.push(i); st += sums[i]; } else { bottom.push(i); sb += sums[i]; } }
  return bottom.reverse().concat(top);
})();

/* ── offsets: returns [y0, y1] per layer per week in data units, plus domain ── */
function layout(mode) {
  const n = GEN.length;
  const base = new Array(M).fill(0);
  if (mode === 'flow') {
    for (let j = 1; j < M; j++) {
      let s1 = 0, s2 = 0;
      for (let a = 0; a < n; a++) {
        const i = order[a];
        let s3 = (V[i][j] - V[i][j - 1]) / 2;
        for (let b = 0; b < a; b++) { const k = order[b]; s3 += V[k][j] - V[k][j - 1]; }
        s1 += V[i][j]; s2 += s3 * V[i][j];
      }
      base[j] = base[j - 1] - (s1 ? s2 / s1 : 0);
    }
    // wiggle drifts over a year; subtract a gaussian-smoothed centre line so the
    // stream keeps its local sway but stays in the middle of the stage
    const c = base.map((b, j) => b + TOT[j] / 2), sm = [];
    for (let j = 0; j < M; j++) {
      let a = 0, wsum = 0;
      for (let k = 0; k < M; k++) { const wt = gauss(k, j, 5); a += c[k] * wt; wsum += wt; }
      sm.push(a / wsum);
    }
    for (let j = 0; j < M; j++) base[j] -= sm[j];
  }
  const Y = GEN.map(() => ({ y0: new Float64Array(M), y1: new Float64Array(M) }));
  let lo = Infinity, hi = -Infinity;
  for (let j = 0; j < M; j++) {
    const k = mode === 'share' ? 1 / TOT[j] : 1;
    let y = base[j] * k;
    for (const i of order) {
      Y[i].y0[j] = y;
      y += V[i][j] * k;
      Y[i].y1[j] = y;
    }
    lo = Math.min(lo, Y[order[0]].y0[j]);
    hi = Math.max(hi, y);
  }
  if (mode === 'stack') lo = 0;
  if (mode === 'flow') { const m = Math.max(-lo, hi); lo = -m; hi = m; }
  return { Y, lo, hi };
}

/* ── geometry ── */
let W = 0, H = 0, top = 22, bot = 18;
const sx = (j) => (j / (M - 1)) * W;
let cur = null, from = null, goal = null, anim = null, mode = 'flow';
function toScreen(L) {
  const span = L.hi - L.lo || 1;
  const k = (H - top - bot) / span;
  return L.Y.map((s) => ({
    y0: Array.from(s.y0, (v) => H - bot - (v - L.lo) * k),
    y1: Array.from(s.y1, (v) => H - bot - (v - L.lo) * k),
  }));
}

function spline(xs, ys, out, rev) {
  const n = xs.length;
  const at = (i) => [xs[i], ys[i]];
  const seq = rev ? [...Array(n).keys()].reverse() : [...Array(n).keys()];
  for (let s = 0; s < n - 1; s++) {
    const i0 = seq[Math.max(0, s - 1)], i1 = seq[s], i2 = seq[s + 1], i3 = seq[Math.min(n - 1, s + 2)];
    const p0 = at(i0), p1 = at(i1), p2 = at(i2), p3 = at(i3);
    const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
    const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
    out.push('C' + c1x.toFixed(1) + ' ' + c1y.toFixed(1) + ' ' + c2x.toFixed(1) + ' ' + c2y.toFixed(1) + ' ' + p2[0].toFixed(1) + ' ' + p2[1].toFixed(1));
  }
}
const xsArr = () => Array.from({ length: M }, (_, j) => sx(j));

const paths = GEN.map((g, i) => {
  const p = document.createElementNS(NS, 'path');
  p.setAttribute('class', 'fxa-stream__layer');
  p.setAttribute('fill', 'var(--fxa-stream-g' + i + ')');
  p.dataset.i = i;
  return p;
});
order.forEach((i) => gL.append(paths[i]));
const labels = GEN.map((g, i) => {
  const t = document.createElementNS(NS, 'text');
  t.textContent = g;
  t.setAttribute('fill', DARK_TEXT[i] ? 'var(--fxa-stream-ink)' : 'var(--fxa-stream-paper)');
  gLab.append(t);
  return t;
});
// the share bar reads left to right in the chart's top-to-bottom order
const segs = GEN.map((g, i) => {
  const s = document.createElement('span');
  s.style.setProperty('--c', 'var(--fxa-stream-g' + i + ')');
  return s;
});
order.slice().reverse().forEach((i) => bar.append(segs[i]));

function render() {
  if (!cur || !W) return;
  const xs = xsArr();
  for (let i = 0; i < GEN.length; i++) {
    const s = cur[i];
    const d = ['M' + xs[0].toFixed(1) + ' ' + s.y1[0].toFixed(1)];
    spline(xs, s.y1, d, false);
    d.push('L' + xs[M - 1].toFixed(1) + ' ' + s.y0[M - 1].toFixed(1));
    spline(xs, s.y0, d, true);
    d.push('Z');
    paths[i].setAttribute('d', d.join(''));
    // label where the layer stays thickest across the whole width of its word
    const half = GEN[i].length * 3.1 + 4;
    const win = Math.ceil(half / (W / (M - 1)));
    let bj = -1, bt = 0;
    for (let j = win; j < M - win; j++) {
      let th = Infinity;
      for (let k = j - win; k <= j + win; k++) th = Math.min(th, s.y0[k] - s.y1[k]);
      if (th > bt) { bt = th; bj = j; }
    }
    const lab = labels[i];
    const fits = bt > 12 && W > 200;
    lab.style.display = fits ? '' : 'none';
    if (fits) {
      lab.setAttribute('x', xs[bj].toFixed(1));
      lab.setAttribute('y', ((s.y0[bj] + s.y1[bj]) / 2).toFixed(1));
    }
  }
  // annotations sit above the whole stack at their week
  gN.textContent = '';
  for (const n of NOTES) {
    const s = cur[n.g];
    const x = xs[n.w];
    let ceil = Infinity;
    for (const i of order) ceil = Math.min(ceil, cur[i].y1[n.w]);
    const ty = Math.max(10, ceil - 10);
    const ly = (s.y0[n.w] + s.y1[n.w]) / 2;
    const ln = document.createElementNS(NS, 'line');
    ln.setAttribute('x1', x); ln.setAttribute('x2', x);
    ln.setAttribute('y1', ty + 4); ln.setAttribute('y2', ly);
    const c = document.createElementNS(NS, 'circle');
    c.setAttribute('cx', x); c.setAttribute('cy', ly); c.setAttribute('r', 1.8);
    const t = document.createElementNS(NS, 'text');
    t.textContent = n.text;
    t.setAttribute('x', x + n.side * 4);
    t.setAttribute('y', ty);
    t.setAttribute('text-anchor', n.side < 0 ? 'end' : 'start');
    const g = document.createElementNS(NS, 'g');
    if (n.minor) g.setAttribute('class', 'fxa-stream__note--minor');
    g.append(ln, c, t);
    gN.append(g);
  }
  placeHead();
}

function months() {
  gM.textContent = '';
  const names = 'JFMAMJJASOND';
  for (let m = 0; m < 12; m++) {
    // first ISO week (Monday start, week 1 from 30 Dec 2024) that contains the 1st of the month
    const d = Date.UTC(2025, m, 1), w0 = Date.UTC(2024, 11, 30);
    const j = Math.min(M - 1, Math.floor((d - w0) / 864e5 / 7));
    const x = sx(j);
    const t = document.createElementNS(NS, 'text');
    t.textContent = names[m];
    t.setAttribute('x', (x + 3).toFixed(1));
    t.setAttribute('y', (H - 4).toFixed(1));
    const l = document.createElementNS(NS, 'line');
    l.setAttribute('x1', x); l.setAttribute('x2', x);
    l.setAttribute('y1', H - 13); l.setAttribute('y2', H);
    gM.append(l, t);
  }
}

/* ── week readout ── */
let wk = 26, act = null;
const fmt = new Intl.NumberFormat('en-GB');
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function dates(j) {
  const a = new Date(Date.UTC(2024, 11, 30) + j * 7 * 864e5), b = new Date(a.getTime() + 6 * 864e5);
  const f = (d) => d.getUTCDate() + ' ' + MON[d.getUTCMonth()];
  return f(a) + ' – ' + f(b);
}
function biggest(j) {
  let bi = 0;
  for (let i = 1; i < GEN.length; i++) if (V[i][j] > V[bi][j]) bi = i;
  return bi;
}
function readout(quiet) {
  // the autoplay tour must not talk over a screen reader; only people moving the playhead do
  R('gname').parentElement.setAttribute('aria-live', quiet ? 'off' : 'polite');
  const j = wk;
  R('wk').textContent = 'Wk ' + (j + 1);
  R('dates').textContent = dates(j);
  R('total').textContent = fmt.format(TOT[j]);
  const g = act ?? biggest(j);
  segs.forEach((s, i) => {
    s.style.setProperty('--v', V[i][j]);
    s.classList.toggle('is-on', act === i);
  });
  paths.forEach((p, i) => p.classList.toggle('is-on', act === i));
  labels.forEach((t, i) => t.classList.toggle('is-on', act === i));
  R('sw').style.setProperty('--c', 'var(--fxa-stream-g' + g + ')');
  R('gname').textContent = GEN[g];
  const share = ((V[g][j] / TOT[j]) * 100).toFixed(1);
  R('gval').textContent = (act === null ? 'leads with ' : '') + fmt.format(V[g][j]) + ' h · ' + share + '% of the week';
  svg.setAttribute('aria-valuenow', j + 1);
  svg.setAttribute('aria-valuetext', 'Week ' + (j + 1) + ', ' + dates(j) + ': ' + fmt.format(TOT[j]) +
    ' hours. ' + GEN[g] + ' ' + fmt.format(V[g][j]) + ' hours, ' + share + ' percent.');
  placeHead();
}
function placeHead() {
  if (!cur || !W) return;
  const x = sx(wk);
  play.style.transform = 'translateX(' + x.toFixed(1) + 'px)';
  rule.setAttribute('y1', 4);
  rule.setAttribute('y2', H - bot);
  const g = act ?? biggest(wk);
  dot.style.transform = 'translateY(' + ((cur[g].y0[wk] + cur[g].y1[wk]) / 2).toFixed(1) + 'px)';
}

/* ── layout morph: per-layer damped spring on progress, staggered ── */
let raf = 0, seen = true, last = 0;
function spring(t) { return t >= 1 ? 1 : 1 - Math.exp(-6.5 * t) * Math.cos(7.5 * t); }
function setMode(m, focusIt) {
  if (m === mode && cur) return;
  mode = m;
  radios.forEach((b) => {
    const on = b.dataset.mode === m;
    b.setAttribute('aria-checked', String(on));
    b.tabIndex = on ? 0 : -1;
    if (on && focusIt) b.focus();
  });
  goal = toScreen(layout(m));
  if (calm || !cur) { cur = goal; anim = null; render(); return; }
  from = cur.map((s) => ({ y0: s.y0.slice(), y1: s.y1.slice() }));
  anim = { t0: performance.now(), dur: 900 };
  kick();
}
radios.forEach((b, i) => {
  b.addEventListener('click', () => setMode(b.dataset.mode, false));
  b.addEventListener('keydown', (e) => {
    let j = -1;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % radios.length;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i + radios.length - 1) % radios.length;
    if (j < 0) return;
    e.preventDefault();
    setMode(radios[j].dataset.mode, true);
  });
});

/* ── autoplay: the playhead tours the year until someone takes over ── */
let idleAt = -1e9, held = false, stepClock = 0;
function kick() {
  if (!raf && seen && !document.hidden && root.isConnected) raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
  last = now;
  if (anim) {
    const p = (now - anim.t0) / anim.dur;
    cur = goal.map((g, i) => {
      const a = order.indexOf(i);
      const k = spring(Math.max(0, Math.min(1, (p * anim.dur - a * 40) / (anim.dur - 240))));
      const f = from[i];
      return {
        y0: g.y0.map((v, j) => f.y0[j] + (v - f.y0[j]) * k),
        y1: g.y1.map((v, j) => f.y1[j] + (v - f.y1[j]) * k),
      };
    });
    if (p >= 1) { cur = goal; anim = null; }
    render();
  }
  const auto = !calm && !held && now - idleAt > 2600;
  if (auto) {
    stepClock += dt;
    if (stepClock > 0.85) { stepClock = 0; wk = (wk + 1) % M; act = null; readout(true); }
  }
  if (anim || !calm) kick();
  else last = 0;
}

/* ── pointer and keyboard on the chart ── */
function pick(e) {
  const r = svg.getBoundingClientRect();
  const x = e.clientX - r.left, y = e.clientY - r.top;
  const j = Math.max(0, Math.min(M - 1, Math.round((x / W) * (M - 1))));
  let g = null;
  if (cur) for (let i = 0; i < GEN.length; i++) if (y >= cur[i].y1[j] - 1 && y <= cur[i].y0[j] + 1) { g = i; break; }
  return [j, g];
}
svg.addEventListener('pointermove', (e) => {
  const [j, g] = pick(e);
  held = true;
  if (j !== wk || g !== act) { wk = j; act = g; readout(); }
});
svg.addEventListener('pointerdown', (e) => {
  const [j, g] = pick(e);
  held = true;
  wk = j; act = g;
  readout();
});
svg.addEventListener('pointerleave', () => {
  held = document.activeElement === svg;
  idleAt = performance.now();
  if (!held && act !== null) { act = null; readout(); }
});
svg.addEventListener('focus', () => { held = true; });
svg.addEventListener('blur', () => { held = false; idleAt = performance.now(); });
svg.addEventListener('keydown', (e) => {
  const k = e.key;
  if (k === 'ArrowRight') wk = Math.min(M - 1, wk + 1);
  else if (k === 'ArrowLeft') wk = Math.max(0, wk - 1);
  else if (k === 'PageUp') wk = Math.min(M - 1, wk + 4);
  else if (k === 'PageDown') wk = Math.max(0, wk - 4);
  else if (k === 'Home') wk = 0;
  else if (k === 'End') wk = M - 1;
  else if (k === 'ArrowUp' || k === 'ArrowDown') {
    // walk the layers in visual order, top to bottom
    const vis = order.slice().reverse();
    const p = act === null ? -1 : vis.indexOf(act);
    const q = k === 'ArrowDown' ? Math.min(vis.length - 1, p + 1) : Math.max(0, p < 0 ? 0 : p - 1);
    act = vis[q];
  } else if (k === 'Escape') { if (act === null) return; act = null; }
  else return;
  e.preventDefault();
  held = true;
  readout();
});

/* ── lifecycle ── */
function size() {
  const r = svg.getBoundingClientRect();
  const w = Math.round(r.width), h = Math.round(r.height);
  if (!w || !h || (w === W && h === H)) return;
  W = w; H = h;
  top = 22; bot = 18;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  goal = toScreen(layout(mode));
  cur = goal; anim = null;
  months();
  render();
  readout();
}
function onVis() {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) { last = 0; kick(); }
}
document.addEventListener('visibilitychange', onVis);
function onMotion() {
  if (!root.isConnected) { mq.removeEventListener('change', onMotion); return; }
  calm = mq.matches;
  kick();
}
mq.addEventListener('change', onMotion);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  size();
});
ro.observe(svg);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  seen = entries[entries.length - 1].isIntersecting;
  if (seen) { last = 0; kick(); }
});
io.observe(root);

if (calm) wk = 51;
size();
readout(true);
kick();

css:
@property --fxa-sunburst-a {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
@property --fxa-sunburst-fill {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

.fxa-sunburst {
  /* Re-theme with the ground, the text and the four top-level hues. */
  --fxa-sunburst-ground: oklch(0.2 0.02 168);
  --fxa-sunburst-text: oklch(0.95 0.012 110);
  --fxa-sunburst-h0: oklch(0.76 0.13 58);
  --fxa-sunburst-h1: oklch(0.72 0.08 190);
  --fxa-sunburst-h2: oklch(0.84 0.12 100);
  --fxa-sunburst-h3: oklch(0.68 0.1 15);

  --fxa-sunburst-muted: color-mix(in oklch, var(--fxa-sunburst-text) 58%, var(--fxa-sunburst-ground));
  --fxa-sunburst-line: color-mix(in oklch, var(--fxa-sunburst-text) 13%, transparent);
  --fxa-sunburst-raise: color-mix(in oklch, var(--fxa-sunburst-text) 6%, var(--fxa-sunburst-ground));
  --fxa-sunburst-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-sunburst-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 1.02;
  min-block-size: 340px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-sunburst-text);
  background:
    radial-gradient(70% 60% at 50% 62%, color-mix(in oklch, var(--fxa-sunburst-ground) 82%, var(--fxa-sunburst-h1)) 0%, transparent 72%),
    var(--fxa-sunburst-ground);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-sunburst-line);

  & .fxa-sunburst__body {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-areas:
      "head cap"
      "crumbs crumbs"
      "chart chart";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto auto minmax(0, 1fr);
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
  }

  & .fxa-sunburst__head { grid-area: head; min-inline-size: 0; }
  & .fxa-sunburst__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-sunburst-muted);
  }
  & .fxa-sunburst__title {
    margin: 5px 0 0;
    font-size: clamp(19px, 6.2cqi, 27px);
    font-weight: 300;
    line-height: 1.02;
    letter-spacing: -0.025em;
    text-wrap: balance;
    & span { font-weight: 700; font-variant-numeric: tabular-nums; }
  }

  & .fxa-sunburst__cap {
    grid-area: cap;
    align-self: start;
    display: grid;
    justify-items: end;
    gap: 6px;
    padding-block-start: 2px;
  }
  & .fxa-sunburst__capbar {
    position: relative;
    inline-size: clamp(64px, 22cqi, 96px);
    block-size: 6px;
    border-radius: 3px;
    overflow: hidden;
    background: var(--fxa-sunburst-line);
    & i {
      position: absolute;
      inset: 0;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--fxa-sunburst-h0), var(--fxa-sunburst-h2));
      transform-origin: 0 50%;
      scale: var(--fxa-sunburst-fill) 1;
      transition: --fxa-sunburst-fill 1.4s var(--fxa-sunburst-out) 0.3s;
      @starting-style { --fxa-sunburst-fill: 0; }
    }
  }
  & .fxa-sunburst__captext {
    font: 500 10.5px/1 system-ui, sans-serif;
    color: var(--fxa-sunburst-muted);
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxa-sunburst-text); font: 650 12px/1 ui-monospace, Menlo, monospace; }
  }

  & .fxa-sunburst__crumbs {
    grid-area: crumbs;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 2px;
    margin-block-start: 8px;
    min-block-size: 24px;
    & button {
      appearance: none;
      margin: 0;
      border: 0;
      padding: 4px 7px;
      border-radius: 6px;
      background: transparent;
      color: var(--fxa-sunburst-muted);
      font: 600 11px/1 system-ui, sans-serif;
      cursor: pointer;
      transition: background-color 0.2s linear, color 0.2s linear, opacity 0.35s var(--fxa-sunburst-out), translate 0.5s var(--fxa-sunburst-spring);
      @starting-style { opacity: 0; translate: -6px 0; }
    }
    & button:hover { background: var(--fxa-sunburst-raise); color: var(--fxa-sunburst-text); }
    & button[aria-current="page"] { color: var(--fxa-sunburst-text); cursor: default; }
    & button:focus-visible { outline: 2px solid var(--fxa-sunburst-h0); outline-offset: 1px; }
    & svg { inline-size: 10px; block-size: 10px; fill: none; stroke: var(--fxa-sunburst-muted); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
    & button { display: inline-flex; align-items: center; gap: 5px; }
    & .fxa-sunburst__drive { inline-size: 14px; block-size: 14px; stroke: currentColor; stroke-width: 1.3; }
  }

  & .fxa-sunburst__chart {
    grid-area: chart;
    position: relative;
    min-block-size: 0;
  }
  & .fxa-sunburst__svg {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    display: block;
    overflow: visible;
  }
  & .fxa-sunburst__arc {
    stroke: none;
    cursor: pointer;
    outline: none;
    transition: transform 0.45s var(--fxa-sunburst-spring), filter 0.25s linear;
  }
  & .fxa-sunburst__arc[data-leaf] { cursor: default; }
  & .fxa-sunburst__arc:hover,
  & .fxa-sunburst__arc.is-hot { filter: brightness(1.14) saturate(1.1); }
  & .fxa-sunburst__arc:focus-visible { stroke: var(--fxa-sunburst-text); stroke-width: 2; }
  & .fxa-sunburst__arcs:has(.is-hot) .fxa-sunburst__arc:not(.is-hot):not(.is-trail) { filter: saturate(0.55) brightness(0.8); }

  & .fxa-sunburst__labels text {
    font: 650 10px/1 system-ui, sans-serif;
    letter-spacing: 0.01em;
    text-anchor: middle;
    dominant-baseline: central;
    fill: color-mix(in oklch, var(--fxa-sunburst-ground) 88%, black);
    pointer-events: none;
  }

  & .fxa-sunburst__sheen {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: conic-gradient(from var(--fxa-sunburst-a) at 50% 50%,
      transparent 0deg,
      color-mix(in oklch, white 26%, transparent) 16deg,
      transparent 46deg,
      transparent 360deg);
    mix-blend-mode: soft-light;
    mask: radial-gradient(circle at 50% 50%,
      transparent var(--fxa-sunburst-r0, 40px),
      #000 calc(var(--fxa-sunburst-r0, 40px) + 1px),
      #000 var(--fxa-sunburst-r1, 120px),
      transparent calc(var(--fxa-sunburst-r1, 120px) + 1px));
    animation: fxa-sunburst-spin 9s linear infinite;
  }

  & .fxa-sunburst__core {
    appearance: none;
    position: absolute;
    left: 50%;
    top: 50%;
    inline-size: calc(var(--fxa-sunburst-r0, 40px) * 2 - 6px);
    block-size: calc(var(--fxa-sunburst-r0, 40px) * 2 - 6px);
    overflow: hidden;
    translate: -50% -50%;
    margin: 0;
    border: 0;
    border-radius: 50%;
    display: grid;
    place-content: center;
    justify-items: center;
    gap: 3px;
    padding: 6px;
    background: radial-gradient(circle at 50% 35%, var(--fxa-sunburst-raise), var(--fxa-sunburst-ground) 75%);
    box-shadow: inset 0 0 0 1px var(--fxa-sunburst-line);
    color: var(--fxa-sunburst-text);
    text-align: center;
    cursor: default;
    transition: box-shadow 0.2s linear, scale 0.45s var(--fxa-sunburst-spring);
  }
  & .fxa-sunburst__core[data-up] { cursor: zoom-out; }
  & .fxa-sunburst__core[data-up]:hover { box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--fxa-sunburst-text) 40%, transparent); }
  & .fxa-sunburst__core[data-up]:active { scale: 0.96; }
  & .fxa-sunburst__core:focus-visible { outline: 2px solid var(--fxa-sunburst-h0); outline-offset: 2px; }
  & .fxa-sunburst__cname {
    max-inline-size: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font: 600 10px/1.15 system-ui, sans-serif;
    color: var(--fxa-sunburst-muted);
  }
  & .fxa-sunburst__core[data-roomy] .fxa-sunburst__cname {
    white-space: normal;
    max-inline-size: 12ch;
    text-wrap: balance;
    font-size: 10.5px;
  }
  & .fxa-sunburst__csize {
    font: 700 clamp(14px, 4.2cqi, 19px)/1 ui-monospace, Menlo, monospace;
    white-space: nowrap;
    letter-spacing: -0.03em;
    font-variant-numeric: tabular-nums;
  }
  & .fxa-sunburst__cshare {
    display: none;
    font: 500 9.5px/1.1 system-ui, sans-serif;
    color: var(--fxa-sunburst-muted);
    font-variant-numeric: tabular-nums;
  }
  & .fxa-sunburst__core[data-roomy] .fxa-sunburst__cshare { display: block; }
  & .fxa-sunburst__up {
    inline-size: 12px;
    block-size: 12px;
    fill: none;
    stroke: var(--fxa-sunburst-muted);
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
    display: none;
    opacity: 0;
    translate: 0 3px;
    transition: opacity 0.2s linear, translate 0.35s var(--fxa-sunburst-spring);
  }
  & .fxa-sunburst__core[data-up] .fxa-sunburst__up {
    display: block;
    opacity: 1;
    translate: 0 0;
    @starting-style { opacity: 0; translate: 0 3px; }
  }

  & .fxa-sunburst__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@keyframes fxa-sunburst-spin {
  to { --fxa-sunburst-a: 360deg; }
}

@container (max-width: 320px) {
  .fxa-sunburst .fxa-sunburst__cap { display: none; }
  .fxa-sunburst .fxa-sunburst__cshare { display: none; }
}
@container (min-width: 600px) {
  .fxa-sunburst .fxa-sunburst__body {
    grid-template-areas:
      "head chart"
      "cap chart"
      "crumbs chart";
    grid-template-columns: minmax(180px, 34%) minmax(0, 1fr);
    grid-template-rows: auto auto 1fr;
    row-gap: 14px;
  }
  .fxa-sunburst .fxa-sunburst__cap { justify-items: start; }
  .fxa-sunburst .fxa-sunburst__crumbs { align-self: end; }
}

@media (prefers-reduced-motion: reduce) {
  .fxa-sunburst {
    & .fxa-sunburst__sheen { animation: none; opacity: 0; }
    & .fxa-sunburst__arc,
    & .fxa-sunburst__core,
    & .fxa-sunburst__up,
    & .fxa-sunburst__crumbs button,
    & .fxa-sunburst__capbar i { transition: none; }
  }
}

js:
/* Volume rings — a zoomable sunburst on a hand-rolled partition.
   Each folder owns an angular slice [x0, x1] of the unit turn proportional to its
   size, and a ring equal to its depth. Zooming re-maps every slice into the
   focus's range and shifts every ring by the focus's depth; arcs tween their
   start, end and ring together, so three rings are always on stage. */
const NS = 'http://www.w3.org/2000/svg';
const svg = root.querySelector('.fxa-sunburst__svg');
const gA = root.querySelector('.fxa-sunburst__arcs');
const gT = root.querySelector('.fxa-sunburst__labels');
const chart = root.querySelector('.fxa-sunburst__chart');
const core = root.querySelector('.fxa-sunburst__core');
const crumbs = root.querySelector('.fxa-sunburst__crumbs');
const live = root.querySelector('.fxa-sunburst__sr');
const C = (k) => root.querySelector('[data-c="' + k + '"]');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const CAPACITY = 4000; // GB
const DATA = {
  name: 'Studio volume', short: 'Studio', children: [
    { name: 'Client work', short: 'Clients', children: [
      { name: 'Halvard Hotels rebrand', short: 'Halvard', children: [
        { name: 'Footage', v: 212 }, { name: 'Renders', v: 148 }, { name: 'Design files', short: 'Design', v: 64 }, { name: 'Exports', v: 21 }] },
      { name: 'Museum of Tides', short: 'Tides', children: [
        { name: 'Video', v: 174 }, { name: 'Audio', v: 41 }, { name: 'Layouts', v: 29 }, { name: 'Type specimens', short: 'Type', v: 6 }] },
      { name: 'Pell & Ivers packaging', short: 'Pell & Ivers', children: [
        { name: '3D scenes', short: '3D', v: 96 }, { name: 'Photography', short: 'Photo', v: 88 }, { name: 'Print PDFs', short: 'Print', v: 18 }] },
    ] },
    { name: 'Archive', children: [
      { name: '2023 projects', short: '2023', v: 241 }, { name: '2024 projects', short: '2024', v: 198 }, { name: '2022 projects', short: '2022', v: 186 }] },
    { name: 'Library', children: [
      { name: 'Stock footage', short: 'Stock', v: 132 }, { name: 'Textures', v: 46 }, { name: 'Sound effects', short: 'SFX', v: 27 }, { name: 'Fonts', v: 3 }] },
    { name: 'Backups', children: [
      { name: 'Laptops', v: 118 }, { name: 'Mail', v: 22 }, { name: 'Accounts', v: 9 }] },
  ],
};

/* ── partition ── */
const nodes = [];
(function walk(n, parent, depth, hue) {
  n.parent = parent; n.depth = depth; n.short = n.short || n.name;
  n.hue = hue;
  nodes.push(n);
  if (n.children) {
    n.children.forEach((c, i) => walk(c, n, depth + 1, depth === 0 ? i : hue));
    n.children.sort((a, b) => b.v - a.v);
  }
})(DATA, null, 0, 0);
