css:
.fxa-chord {
  /* Re-theme with ground, text, and the shared lightness and chroma of the team inks. */
  --fxa-chord-ground: oklch(0.19 0.007 260);
  --fxa-chord-text: oklch(0.95 0.006 260);
  --fxa-chord-l: 0.74;
  --fxa-chord-c: 0.13;

  --fxa-chord-t0: oklch(var(--fxa-chord-l) calc(var(--fxa-chord-c) * 0.8) 235);
  --fxa-chord-t1: oklch(calc(var(--fxa-chord-l) + 0.06) var(--fxa-chord-c) 78);
  --fxa-chord-t2: oklch(calc(var(--fxa-chord-l) - 0.04) calc(var(--fxa-chord-c) * 1.2) 28);
  --fxa-chord-t3: oklch(var(--fxa-chord-l) calc(var(--fxa-chord-c) * 0.95) 158);
  --fxa-chord-t4: oklch(calc(var(--fxa-chord-l) - 0.02) calc(var(--fxa-chord-c) * 0.85) 305);
  --fxa-chord-t5: oklch(calc(var(--fxa-chord-l) + 0.1) calc(var(--fxa-chord-c) * 0.8) 112);
  --fxa-chord-t6: oklch(calc(var(--fxa-chord-l) - 0.07) var(--fxa-chord-c) 355);

  --fxa-chord-muted: color-mix(in oklch, var(--fxa-chord-text) 56%, var(--fxa-chord-ground));
  --fxa-chord-line: color-mix(in oklch, var(--fxa-chord-text) 12%, transparent);
  --fxa-chord-raise: color-mix(in oklch, var(--fxa-chord-text) 7%, var(--fxa-chord-ground));
  --fxa-chord-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-chord-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 1.02;
  min-block-size: 340px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-chord-text);
  background:
    radial-gradient(60% 55% at 50% 52%, var(--fxa-chord-raise) 0%, transparent 70%),
    var(--fxa-chord-ground);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-chord-line);

  & .fxa-chord__body {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-areas:
      "head switch"
      "chart chart"
      "read read";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto minmax(0, 1fr) auto;
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
  }

  & .fxa-chord__head { grid-area: head; min-inline-size: 0; }
  & .fxa-chord__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-chord-muted);
  }
  & .fxa-chord__title {
    margin: 5px 0 0;
    font-size: clamp(19px, 6.2cqi, 27px);
    font-weight: 700;
    line-height: 1;
    letter-spacing: -0.03em;
    text-wrap: balance;
  }

  & .fxa-chord__switch {
    grid-area: switch;
    align-self: start;
    position: relative;
    display: inline-grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    padding: 3px;
    border-radius: 9px;
    background: var(--fxa-chord-raise);
    box-shadow: inset 0 0 0 1px var(--fxa-chord-line);
    & button {
      appearance: none;
      position: relative;
      z-index: 1;
      margin: 0;
      border: 0;
      padding: 6px 10px;
      border-radius: 6px;
      background: transparent;
      color: var(--fxa-chord-muted);
      font: 650 11px/1 ui-monospace, Menlo, monospace;
      cursor: pointer;
      transition: color 0.2s linear;
    }
    & button:hover { color: var(--fxa-chord-text); }
    & button[aria-checked="true"] { color: var(--fxa-chord-ground); }
    & button:focus-visible { outline: 2px solid var(--fxa-chord-text); outline-offset: 1px; }
    &::before {
      content: "";
      position: absolute;
      inset-block: 3px;
      inset-inline-start: 3px;
      inline-size: calc((100% - 6px) / 2);
      border-radius: 6px;
      background: var(--fxa-chord-text);
      transition: translate 0.5s var(--fxa-chord-spring);
    }
    &:has([data-q="1"][aria-checked="true"])::before { translate: 100% 0; }
  }

  & .fxa-chord__chart { grid-area: chart; position: relative; min-block-size: 0; margin-block: 4px; }
  & .fxa-chord__svg {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    display: block;
    overflow: visible;
  }

  & .fxa-chord__ribbon {
    fill-opacity: 0.74;
    stroke: color-mix(in oklch, var(--fxa-chord-ground) 60%, transparent);
    stroke-width: 0.5;
    mix-blend-mode: screen;
    transition: fill-opacity 0.35s var(--fxa-chord-out), opacity 0.6s var(--fxa-chord-out), scale 0.9s var(--fxa-chord-spring);
    transition-delay: 0s, calc(var(--i) * 22ms + 120ms), calc(var(--i) * 22ms + 120ms);
    transform-origin: 0 0;
    @starting-style { opacity: 0; scale: 0.4; }
  }
  & .fxa-chord__svg[data-focus] .fxa-chord__ribbon { fill-opacity: 0.06; transition-delay: 0s; }
  & .fxa-chord__svg[data-focus] .fxa-chord__ribbon.is-on { fill-opacity: 0.88; }

  & .fxa-chord__group {
    cursor: pointer;
    outline: none;
    transition: opacity 0.3s var(--fxa-chord-out);
  }
  & .fxa-chord__svg[data-focus] .fxa-chord__group:not(.is-on):not(.is-peer) { opacity: 0.35; }
  & .fxa-chord__group:focus-visible .fxa-chord__band { stroke: var(--fxa-chord-text); stroke-width: 1.5; }
  & .fxa-chord__hit { fill: transparent; }


  & .fxa-chord__names text {
    font: 650 10px/1 system-ui, sans-serif;
    letter-spacing: 0.02em;
    fill: var(--fxa-chord-text);
    transition: opacity 0.3s linear;
  }
  & .fxa-chord__svg[data-focus] .fxa-chord__names text:not(.is-on):not(.is-peer) { opacity: 0.35; }

  & .fxa-chord__read {
    grid-area: read;
    display: grid;
    gap: 4px;
    min-block-size: 36px;
    align-content: end;
  }
  & .fxa-chord__lead {
    margin: 0;
    font: 500 12px/1.35 system-ui, sans-serif;
    color: var(--fxa-chord-muted);
    font-variant-numeric: tabular-nums;
    text-wrap: pretty;
    & b { font: 700 clamp(15px, 4.6cqi, 19px)/1 ui-monospace, Menlo, monospace; color: var(--fxa-chord-text); letter-spacing: -0.02em; margin-inline: 0 3px; }
    & i { font-style: normal; color: var(--c); font-weight: 650; margin-inline-end: 6px; }
  }
  & .fxa-chord__line {
    margin: 0;
    display: flex;
    flex-wrap: wrap;
    gap: 3px 12px;
    font: 500 11px/1.25 system-ui, sans-serif;
    color: var(--fxa-chord-muted);
    font-variant-numeric: tabular-nums;
    text-wrap: pretty;
    & span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
    & svg { inline-size: 12px; block-size: 12px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
    & b { color: var(--fxa-chord-text); font-weight: 650; }
    & em { font-style: normal; color: var(--c); font-weight: 650; }
  }
}

@container (min-width: 600px) {
  .fxa-chord .fxa-chord__body {
    grid-template-areas:
      "head chart"
      "switch chart"
      "read chart";
    grid-template-columns: minmax(200px, 36%) minmax(0, 1fr);
    grid-template-rows: auto auto 1fr;
    row-gap: 14px;
  }
  .fxa-chord .fxa-chord__switch { justify-self: start; }
  .fxa-chord .fxa-chord__read { align-content: end; }
  .fxa-chord .fxa-chord__line { flex-direction: column; }
}

@media (prefers-reduced-motion: reduce) {
  .fxa-chord {
    & .fxa-chord__ribbon,
    & .fxa-chord__group,
    & .fxa-chord__names text,
    & .fxa-chord__switch::before { transition: none; }
  }
}

