/* Who reviews whom — a chord diagram laid out by hand from a 7x7 matrix.
   M[i][j] counts pull requests written by team i and reviewed by team j. Each
   team's arc is its row sum; inside it, sub-arcs run counter-clockwise
   neighbour first so ribbons leave from the side facing their partner. A
   ribbon joins sub-arc (i,j) to (j,i) with two quadratic curves through the
   centre. Switching quarter tweens the matrix itself and re-lays every frame. */
const NS = 'http://www.w3.org/2000/svg';
const svg = root.querySelector('.fxa-chord__svg');
const defs = root.querySelector('.fxa-chord__defs');
const gR = root.querySelector('.fxa-chord__ribbons');
const gG = root.querySelector('.fxa-chord__groups');
const gN = root.querySelector('.fxa-chord__names');
const chart = root.querySelector('.fxa-chord__chart');
const read = root.querySelector('.fxa-chord__read');
const lead = root.querySelector('[data-r="lead"]');
const line = root.querySelector('[data-r="line"]');
const radios = [...root.querySelectorAll('.fxa-chord__switch [role="radio"]')];
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;
const uid = 'fxa-chord-' + Math.random().toString(36).slice(2, 8);

const TEAMS = ['Platform', 'Payments', 'Mobile', 'Web', 'Data', 'Design Systems', 'Security'];
const SHORT = ['Platform', 'Payments', 'Mobile', 'Web', 'Data', 'Design', 'Security'];
const TINY = ['Plat', 'Pay', 'Mob', 'Web', 'Data', 'DS', 'Sec'];
const Q = [
  [ // Q2 2026
    [0, 41, 25, 38, 49, 10, 36],
    [66, 0, 19, 31, 28, 5, 34],
    [52, 18, 0, 47, 11, 22, 15],
    [57, 29, 49, 0, 17, 41, 19],
    [61, 26, 12, 13, 0, 3, 22],
    [11, 4, 19, 33, 2, 0, 5],
    [38, 16, 9, 14, 18, 1, 0],
  ],
  [ // Q3 2026
    [0, 38, 22, 41, 57, 12, 64],
    [84, 0, 17, 29, 33, 6, 71],
    [46, 21, 0, 52, 14, 39, 18],
    [61, 26, 44, 0, 19, 73, 22],
    [72, 31, 9, 15, 0, 4, 27],
    [18, 5, 36, 58, 3, 0, 7],
    [49, 23, 11, 17, 21, 2, 0],
  ],
];
const N = TEAMS.length;
const TAU = Math.PI * 2;
const fmt = new Intl.NumberFormat('en-GB');
const sum = (a) => a.reduce((s, v) => s + v, 0);
const totalOf = (M) => sum(M.map(sum));

/* ── elements ── */
const ribbons = [];
for (let i = 0; i < N; i++) {
  for (let j = i + 1; j < N; j++) {
    const gr = document.createElementNS(NS, 'linearGradient');
    gr.id = uid + '-' + i + '-' + j;
    gr.setAttribute('gradientUnits', 'userSpaceOnUse');
    const s0 = document.createElementNS(NS, 'stop'), s1 = document.createElementNS(NS, 'stop');
    s0.setAttribute('offset', '0'); s1.setAttribute('offset', '1');
    s0.style.stopColor = 'var(--fxa-chord-t' + i + ')';
    s1.style.stopColor = 'var(--fxa-chord-t' + j + ')';
    gr.append(s0, s1);
    defs.append(gr);
    const p = document.createElementNS(NS, 'path');
    p.setAttribute('class', 'fxa-chord__ribbon');
    p.setAttribute('fill', 'url(#' + gr.id + ')');
    p.style.setProperty('--i', ribbons.length);
    gR.append(p);
    ribbons.push({ i, j, el: p, gr });
  }
}
const groups = TEAMS.map((name, i) => {
  const g = document.createElementNS(NS, 'g');
  g.setAttribute('class', 'fxa-chord__group');
  g.setAttribute('role', 'option');
  g.setAttribute('aria-selected', 'false');
  g.tabIndex = i === 0 ? 0 : -1;
  const hit = document.createElementNS(NS, 'path');
  hit.setAttribute('class', 'fxa-chord__hit');
  const band = document.createElementNS(NS, 'path');
  band.setAttribute('class', 'fxa-chord__band');
  band.style.fill = 'var(--fxa-chord-t' + i + ')';
  g.append(hit, band);
  gG.append(g);
  const tp = document.createElementNS(NS, 'path');
  tp.id = uid + '-n' + i;
  tp.setAttribute('fill', 'none');
  defs.append(tp);
  const t = document.createElementNS(NS, 'text');
  const tpath = document.createElementNS(NS, 'textPath');
  tpath.setAttribute('href', '#' + tp.id);
  tpath.setAttribute('startOffset', '50%');
  tpath.setAttribute('text-anchor', 'middle');
  t.append(tpath);
  gN.append(t);
  return { i, g, hit, band, tp, t, tpath };
});

/* ── layout ── */
let W = 0, H = 0, r = 90;
let M = Q[1].map((row) => row.slice());
let quarter = 1;
const pt = (rad, a) => (Math.sin(a) * rad).toFixed(2) + ' ' + (-Math.cos(a) * rad).toFixed(2);
function arc(rad, a0, a1, sweep) {
  return 'A' + rad.toFixed(2) + ' ' + rad.toFixed(2) + ' 0 ' + (Math.abs(a1 - a0) > Math.PI ? 1 : 0) + ' ' + sweep + ' ' + pt(rad, a1);
}
function layout() {
  const out = M.map(sum);
  const pad = 0.045;
  const k = (TAU - pad * N) / Math.max(1, sum(out));
  const g = [], sub = M.map(() => new Array(N));
  let a = -pad / 2 - 0.06;
  for (let i = 0; i < N; i++) {
    const a0 = a;
    for (let s = 0; s < N - 1; s++) {
      const j = (i - 1 - s + N) % N;
      sub[i][j] = [a, a + M[i][j] * k];
      a += M[i][j] * k;
    }
    g.push([a0, a]);
    a += pad;
  }
  return { g, sub };
}
function render() {
  if (!W) return;
  const L = layout();
  for (const rb of ribbons) {
    const [s0, s1] = L.sub[rb.i][rb.j], [t0, t1] = L.sub[rb.j][rb.i];
    rb.el.setAttribute('d', 'M' + pt(r, s0) + arc(r, s0, s1, 1) + 'Q0 0 ' + pt(r, t0) + arc(r, t0, t1, 1) + 'Q0 0 ' + pt(r, s0) + 'Z');
    const ms = (s0 + s1) / 2, mt = (t0 + t1) / 2;
    rb.gr.setAttribute('x1', (Math.sin(ms) * r).toFixed(1)); rb.gr.setAttribute('y1', (-Math.cos(ms) * r).toFixed(1));
    rb.gr.setAttribute('x2', (Math.sin(mt) * r).toFixed(1)); rb.gr.setAttribute('y2', (-Math.cos(mt) * r).toFixed(1));
  }
  const ri = r + 3, ro = r + 12;
  groups.forEach((G, i) => {
    const [a0, a1] = L.g[i];
    G.band.setAttribute('d', 'M' + pt(ro, a0) + arc(ro, a0, a1, 1) + 'L' + pt(ri, a1) + arc(ri, a1, a0, 0) + 'Z');
    G.hit.setAttribute('d', 'M' + pt(ro + 18, a0) + arc(ro + 18, a0, a1, 1) + 'L' + pt(r - 2, a1) + arc(r - 2, a1, a0, 0) + 'Z');
    const mid = (a0 + a1) / 2, low = Math.cos(mid) < -0.05;
    const nr = low ? ro + 13 : ro + 6;
    G.tp.setAttribute('d', low ? 'M' + pt(nr, a1 + 0.4) + arc(nr, a1 + 0.4, a0 - 0.4, 0) : 'M' + pt(nr, a0 - 0.4) + arc(nr, a0 - 0.4, a1 + 0.4, 1));
    const room = (a1 - a0) * nr;
    const label = room > SHORT[i].length * 6.2 ? SHORT[i] : room > TINY[i].length * 6.4 ? TINY[i] : '';
    if (G.tpath.textContent !== label) G.tpath.textContent = label;
  });
}

/* ── focus and readout ── */
let hover = null, sel = null, tour = -1, tourOn = false;
const tf = () => hover || sel || (tour >= 0 ? { team: tour } : null);
const hue = (i) => 'var(--fxa-chord-t' + i + ')';
function el(tag, text, cls) { const e = document.createElement(tag); if (text != null) e.textContent = text; if (cls) e.className = cls; return e; }
function team(i, tag = 'i') { const e = el(tag, TEAMS[i]); e.style.setProperty('--c', hue(i)); return e; }
const ICON_OUT = '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M2 6h7.5M7 3.5 9.5 6 7 8.5"/></svg>';
const ICON_IN = '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M10 6H2.5M5 3.5 2.5 6 5 8.5"/></svg>';
function chip(icon, parts) {
  const s = el('span');
  s.innerHTML = icon;
  for (const p of parts) s.append(p);
  return s;
}
function paint() {
  const f = tf();
  svg.toggleAttribute('data-focus', !!f);
  for (const rb of ribbons) {
    const on = !!f && (f.team != null ? rb.i === f.team || rb.j === f.team : rb.i === f.a && rb.j === f.b);
    rb.el.classList.toggle('is-on', on);
  }
  groups.forEach((G, i) => {
    const on = !!f && (f.team === i || f.a === i);
    const peer = !!f && (f.team != null ? false : f.b === i);
    G.g.classList.toggle('is-on', on);
    G.g.classList.toggle('is-peer', peer || (!!f && f.team != null));
    G.t.classList.toggle('is-on', on);
    G.t.classList.toggle('is-peer', peer || (!!f && f.team != null));
    G.g.setAttribute('aria-selected', String(sel != null && sel.team === i));
  });
  readout(f);
}
function readout(f) {
  lead.textContent = ''; line.textContent = '';
  read.setAttribute('aria-live', tourOn && !hover && !sel ? 'off' : 'polite');
  if (!f) {
    const tot = totalOf(M), other = totalOf(Q[1 - quarter]);
    lead.append(el('b', fmt.format(tot)), ' cross-team reviews in Q' + (quarter + 2));
    let bi = 0, bj = 1;
    for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) if (M[i][j] > M[bi][bj]) { bi = i; bj = j; }
    const busiest = el('span');
    busiest.append('busiest ', team(bi, 'em'), ' → ', team(bj, 'em'), ' ', el('b', M[bi][bj]));
    const delta = el('span');
    if (quarter === 1) delta.append(el('b', '+' + Math.round(((tot - other) / other) * 100) + '%'), ' on Q2');
    else delta.append(el('b', fmt.format(other - tot)), ' fewer than Q3');
    line.append(busiest, delta);
    return;
  }
  if (f.team != null) {
    const i = f.team;
    const sent = sum(M[i]), got = sum(M.map((row) => row[i]));
    let to = 0, from = 0;
    for (let j = 0; j < N; j++) { if (M[i][j] > M[i][to]) to = j; if (M[j][i] > M[from][i]) from = j; }
    lead.append(team(i), el('b', fmt.format(sent)), ' sent · ', el('b', fmt.format(got)), ' reviewed');
    line.append(chip(ICON_OUT, ['most to ', team(to, 'em'), ' ', el('b', M[i][to])]),
      chip(ICON_IN, ['most for ', team(from, 'em'), ' ', el('b', M[from][i])]));
    return;
  }
  lead.append(team(f.a), ' ⇄ ', team(f.b), ' ', el('b', M[f.a][f.b] + M[f.b][f.a]));
  line.append(chip(ICON_OUT, [team(f.b, 'em'), ' reviewed ', el('b', M[f.a][f.b]), ' of ' + SHORT[f.a] + '’s']),
    chip(ICON_IN, [team(f.a, 'em'), ' reviewed ', el('b', M[f.b][f.a]), ' of ' + SHORT[f.b] + '’s']));
}

/* ── loop: matrix tween + idle tour ── */
let raf = 0, seen = true, last = 0, tw = null, idleAt = performance.now() + 900, tourClock = 0;
function kick() { if (!raf && seen && !document.hidden && root.isConnected) raf = requestAnimationFrame(frame); }
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
  last = now;
  if (tw) {
    const p = Math.min(1, (now - tw.t0) / tw.dur);
    const e = p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2;
    M = tw.from.map((row, i) => row.map((v, j) => v + (tw.to[i][j] - v) * e));
    render();
    if (p >= 1) { M = tw.to.map((row) => row.slice()); tw = null; render(); paint(); }
  }
  tourOn = !calm && !hover && !sel && now - idleAt > 2400;
  if (tourOn) {
    tourClock += dt;
    if (tour < 0 || tourClock > 2.6) { tourClock = 0; tour = (tour + 1) % N; paint(); }
  } else if (tour >= 0) { tour = -1; tourClock = 0; paint(); }
  if (tw || !calm) kick(); else last = 0;
}
function setQuarter(q, focusIt) {
  radios.forEach((b) => {
    const on = +b.dataset.q === q;
    b.setAttribute('aria-checked', String(on));
    b.tabIndex = on ? 0 : -1;
    if (on && focusIt) b.focus();
  });
  if (q === quarter) return;
  quarter = q;
  const to = Q[q].map((row) => row.slice());
  if (calm) { M = to; render(); paint(); return; }
  tw = { from: M.map((row) => row.slice()), to, t0: performance.now(), dur: 950 };
  paint();
  kick();
}
radios.forEach((b, k) => {
  b.addEventListener('click', () => setQuarter(+b.dataset.q, false));
  b.addEventListener('keydown', (e) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    setQuarter(+radios[(k + 1) % radios.length].dataset.q, true);
  });
});

/* ── pointer ── */
function touch() { idleAt = performance.now(); if (tour >= 0) { tour = -1; } }
gG.addEventListener('pointerover', (e) => {
  const G = groups.find((x) => x.g.contains(e.target));
  if (!G) return;
  touch();
  hover = { team: G.i };
  paint();
});
gR.addEventListener('pointerover', (e) => {
  const rb = ribbons.find((x) => x.el === e.target);
  if (!rb) return;
  touch();
  hover = { a: rb.i, b: rb.j };
  paint();
});
svg.addEventListener('pointerleave', () => { hover = null; touch(); paint(); });
gG.addEventListener('click', (e) => {
  const G = groups.find((x) => x.g.contains(e.target));
  if (!G) return;
  sel = sel && sel.team === G.i ? null : { team: G.i };
  touch();
  paint();
});

/* ── keyboard: roving focus over teams ── */
let cursor = 0;
function move(i) {
  groups[cursor].g.tabIndex = -1;
  cursor = (i + N) % N;
  groups[cursor].g.tabIndex = 0;
  groups[cursor].g.focus();
}
gG.addEventListener('keydown', (e) => {
  const k = e.key;
  if (k === 'ArrowRight' || k === 'ArrowDown') move(cursor + 1);
  else if (k === 'ArrowLeft' || k === 'ArrowUp') move(cursor - 1);
  else if (k === 'Home') move(0);
  else if (k === 'End') move(N - 1);
  else if (k === 'Enter' || k === ' ') { sel = sel && sel.team === cursor ? null : { team: cursor }; }
  else if (k === 'Escape') { if (!sel && !hover) return; sel = null; hover = null; }
  else return;
  e.preventDefault();
  touch();
  paint();
});
gG.addEventListener('focusin', (e) => {
  const G = groups.find((x) => x.g === e.target);
  if (!G) return;
  cursor = G.i;
  hover = { team: G.i };
  touch();
  paint();
});
gG.addEventListener('focusout', () => { hover = null; touch(); paint(); });

/* ── lifecycle ── */
function size() {
  const b = chart.getBoundingClientRect();
  const w = Math.round(b.width), h = Math.round(b.height);
  if (!w || !h || (w === W && h === H)) return false;
  W = w; H = h;
  r = Math.max(50, Math.min(W, H) / 2 - 30);
  svg.setAttribute('viewBox', (-W / 2) + ' ' + (-H / 2) + ' ' + W + ' ' + H);
  return true;
}
function onVis() {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) { last = 0; kick(); }
}
document.addEventListener('visibilitychange', onVis);
function onMotion() {
  if (!root.isConnected) { mq.removeEventListener('change', onMotion); return; }
  calm = mq.matches;
  kick();
}
mq.addEventListener('change', onMotion);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  if (size()) render();
});
ro.observe(chart);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  seen = entries[entries.length - 1].isIntersecting;
  if (seen) { last = 0; kick(); }
});
io.observe(root);

size();
render();
paint();
kick();

css:
.fxa-skyline {
  /* Re-theme with paper, ink and the two ends of the distance ramp. */
  --fxa-skyline-paper: oklch(0.972 0.009 92);
  --fxa-skyline-ink: oklch(0.27 0.03 40);
  --fxa-skyline-lo: oklch(0.91 0.06 88);
  --fxa-skyline-hi: oklch(0.5 0.17 30);

  --fxa-skyline-s0: color-mix(in oklch, var(--fxa-skyline-hi) 0%, var(--fxa-skyline-lo));
  --fxa-skyline-s1: color-mix(in oklch, var(--fxa-skyline-hi) 25%, var(--fxa-skyline-lo));
  --fxa-skyline-s2: color-mix(in oklch, var(--fxa-skyline-hi) 50%, var(--fxa-skyline-lo));
  --fxa-skyline-s3: color-mix(in oklch, var(--fxa-skyline-hi) 75%, var(--fxa-skyline-lo));
  --fxa-skyline-s4: var(--fxa-skyline-hi);
  --fxa-skyline-rest: color-mix(in oklch, var(--fxa-skyline-ink) 8%, var(--fxa-skyline-paper));
  --fxa-skyline-muted: color-mix(in oklch, var(--fxa-skyline-ink) 60%, var(--fxa-skyline-paper));
  --fxa-skyline-line: color-mix(in oklch, var(--fxa-skyline-ink) 12%, transparent);
  --fxa-skyline-chip: color-mix(in oklch, var(--fxa-skyline-ink) 5%, var(--fxa-skyline-paper));
  --fxa-skyline-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-skyline-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 0.97;
  min-block-size: 330px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-skyline-ink);
  background:
    linear-gradient(to bottom, transparent 55%, color-mix(in oklch, var(--fxa-skyline-lo) 35%, transparent)),
    var(--fxa-skyline-paper);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-skyline-line);

  & .fxa-skyline__body {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-areas:
      "head stats"
      "bar bar"
      "stage stage"
      "read read";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto auto minmax(0, 1fr) auto;
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
  }

  & .fxa-skyline__head { grid-area: head; min-inline-size: 0; }
  & .fxa-skyline__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-skyline-muted);
  }
  & .fxa-skyline__title {
    margin: 5px 0 0;
    font-size: clamp(19px, 6.2cqi, 27px);
    font-weight: 800;
    line-height: 1;
    letter-spacing: -0.035em;
    text-wrap: balance;
  }

  & .fxa-skyline__stats { grid-area: stats; display: flex; gap: clamp(10px, 3.4cqi, 16px); margin: 0; align-self: start; }
  & .fxa-skyline__stat {
    display: grid;
    justify-items: end;
    gap: 3px;
    transition: opacity 0.5s var(--fxa-skyline-out), translate 0.7s var(--fxa-skyline-spring);
    transition-delay: calc(var(--i) * 60ms + 120ms);
    @starting-style { opacity: 0; translate: 0 6px; }
  }
  & .fxa-skyline__stat dt {
    font: 600 9.5px/1 system-ui, sans-serif;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--fxa-skyline-muted);
    white-space: nowrap;
  }
  & .fxa-skyline__stat dd {
    margin: 0;
    font: 650 clamp(16px, 5cqi, 21px)/1 ui-monospace, Menlo, monospace;
    letter-spacing: -0.03em;
    font-variant-numeric: tabular-nums;
  }

  & .fxa-skyline__bar {
    grid-area: bar;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin-block-start: 12px;
  }
  & .fxa-skyline__switch {
    position: relative;
    display: inline-grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    padding: 3px;
    border-radius: 9px;
    background: var(--fxa-skyline-chip);
    box-shadow: inset 0 0 0 1px var(--fxa-skyline-line);
    & button {
      appearance: none;
      position: relative;
      z-index: 1;
      margin: 0;
      border: 0;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 5px;
      padding: 5px 9px;
      border-radius: 6px;
      background: transparent;
      color: var(--fxa-skyline-muted);
      font: 600 11px/1 system-ui, sans-serif;
      cursor: pointer;
      transition: color 0.2s linear;
    }
    & svg { inline-size: 13px; block-size: 13px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linejoin: round; stroke-linecap: round; }
    & button:hover { color: var(--fxa-skyline-ink); }
    & button[aria-checked="true"] { color: var(--fxa-skyline-paper); }
