/* Training skyline — a year calendar that folds up into a city.
   Every day is a box at (week, weekday) with a height in km. One orthographic
   camera — yaw about the vertical, then pitch toward the viewer — draws both
   views: pitch 0 and height 0 is the flat calendar, and the toggle tweens yaw,
   pitch and height together (columns rising left to right). Boxes are sorted
   back to front each frame and only faces whose turned normal points at the
   viewer are filled. */
const stage = root.querySelector('.fxa-skyline__stage');
const cv = root.querySelector('.fxa-skyline__cv');
const ctx = cv.getContext('2d');
const tip = root.querySelector('.fxa-skyline__tip');
const probe = root.querySelector('.fxa-skyline__probe');
const read = root.querySelector('.fxa-skyline__read');
const readText = root.querySelector('[data-r="text"]');
const outTotal = root.querySelector('[data-k="total"]');
const outLong = root.querySelector('[data-k="long"]');
const radios = [...root.querySelectorAll('.fxa-skyline__switch [role="radio"]')];
const T = (k) => tip.querySelector('[data-t="' + k + '"]');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

/* ── data: one runner's 2026, Monday-first weeks from 29 Dec 2025 ── */
const DAY = 864e5, START = Date.UTC(2025, 11, 29), COLS = 53;
const Y0 = Date.UTC(2026, 0, 1), Y1 = Date.UTC(2027, 0, 1);
const TODAY = Math.round((Date.UTC(2026, 9, 2) - START) / DAY); // Fri 2 Oct 2026
const TODAY_KM = 8;
const WD = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const MO = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const KIND = ['rest', 'intervals', 'easy run', 'tempo', 'shakeout', 'easy run', 'long run'];
const SHARE = [0, 0.16, 0.13, 0.17, 0.05, 0.13, 0.36];
let seed = 2026;
const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
function weekKm(w) {
  if (w < 8) return 30 + w * 1.4;
  if (w < 14) return 42 + (w - 8) * 2.2;
  if (w === 15 || w === 16) return 12; // calf strain
  if (w < 21) return 50 + (w - 14) * 1.5;
  if (w < 33) return 58 + (w - 21) + (w % 4 === 3 ? -14 : 0); // cut-back every fourth week
  if (w < 38) return 74 + (w - 33) * 2.4;
  return w === 38 ? 62 : 48; // taper toward the Harbourline Marathon, 18 Oct
}
const cells = [];
for (let d = 0; d < COLS * 7; d++) {
  const t = START + d * DAY;
  if (t < Y0 || t >= Y1) continue;
  const c = Math.floor(d / 7), r = d % 7;
  let km = 0;
  if (d < TODAY) {
    km = weekKm(c) * SHARE[r] * (0.85 + rnd() * 0.3);
    if (r !== 6 && rnd() < 0.06) km = 0;
    km = Math.min(34, Math.round(km * 10) / 10);
  }
  cells.push({ d, c, r, t, km, future: d > TODAY, today: d === TODAY, h: 0, poly: null, depth: 0 });
}
const todayCell = cells.find((x) => x.today);
let live = calm ? TODAY_KM : 0;
todayCell.km = live;
const fmt1 = new Intl.NumberFormat('en-GB', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const dateOf = (x) => { const dt = new Date(x.t); return WD[x.r] + ' ' + dt.getUTCDate() + ' ' + MO[dt.getUTCMonth()]; };
const kindOf = (x) => (x.km === 0 ? (x.r === 0 ? 'rest day' : 'no run') : KIND[x.r]);
function stats() {
  let s = 0, best = cells[0];
  for (const x of cells) { s += x.km; if (x.km > best.km) best = x; }
  outTotal.textContent = new Intl.NumberFormat('en-GB', { maximumFractionDigits: 0 }).format(s);
  outLong.textContent = fmt1.format(best.km);
