    ramp: [0, 1, 2, 3, 4].map((i) => rgb('--fxa-skyline-s' + i)),
    rest: rgb('--fxa-skyline-rest'), ink: rgb('--fxa-skyline-ink'), paper: rgb('--fxa-skyline-paper'),
    muted: rgb('--fxa-skyline-muted'), hi: rgb('--fxa-skyline-hi'),
