const css = (c, k = 1, a = 1) => 'rgba(' + Math.round(c[0] * k) + ',' + Math.round(c[1] * k) + ',' + Math.round(c[2] * k) + ',' + a + ')';

/* ── camera ── */
let W = 0, H = 0, dpr = 1;
