let yawU = -22, pitchU = 52, drift = 0;
const HMAX = 6.5; // box height, in cells, of a 30 km day
let winC = 0;
let cam = { yaw: 0, pitch: 0, k: 1, ox: 0, oy: 0, sy: 0, cy: 1, sp: 0, cp: 1 };
const S = 1; // world units per cell
function setCam(e) {
  const yaw = (yawU + drift) * e * Math.PI / 180, pitch = pitchU * e * Math.PI / 180;
  cam.sy = Math.sin(yaw); cam.cy = Math.cos(yaw); cam.sp = Math.sin(pitch); cam.cp = Math.cos(pitch);
  // fit the whole grid (and the tallest box) into the stage
  // standing up, the camera frames a window of weeks around the focus instead of the whole year
  const span = Math.max(12, Math.min(COLS, Math.round(W / 16)));
  const c1 = Math.min(COLS, Math.max(span, winC + span * 0.32)), c0 = c1 - span;
  const xa = c0 * e, xb = COLS + (c1 - COLS) * e;
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  const grow = (X, Y, Z) => {
    const p = rawProj(X, Y, Z);
    x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); y0 = Math.min(y0, p[1]); y1 = Math.max(y1, p[1]);
  };
  // the floor of the framed strip, then the real roofs standing on it
  for (const [X, Y] of [[xa, 0], [xb, 0], [xa, 7], [xb, 7]]) grow(X, Y, 0);
  for (const x of cells) {
    if (x.h < 0.05 || x.c + 1 < xa || x.c > xb) continue;
    grow(x.c, x.r, x.h); grow(x.c + 1, x.r, x.h); grow(x.c, x.r + 1, x.h); grow(x.c + 1, x.r + 1, x.h);
  }
