  cam.k = Math.min((W - padX * 2) / (x1 - x0), (H - padT - padB) / (y1 - y0));
  cam.ox = (W - (x1 - x0) * cam.k) / 2 - x0 * cam.k;
  cam.oy = padT + (H - padT - padB - (y1 - y0) * cam.k) / 2 - y0 * cam.k;
}
function rawProj(X, Y, Z) {
  const x = X - COLS / 2, y = Y - 3.5;
  const xr = x * cam.cy - y * cam.sy, yr = x * cam.sy + y * cam.cy;
  return [xr, yr * cam.cp - Z * cam.sp, yr];
}
function proj(X, Y, Z) {
