}
function quad(p) { ctx.beginPath(); ctx.moveTo(p[0][0], p[0][1]); for (let i = 1; i < p.length; i++) ctx.lineTo(p[i][0], p[i][1]); ctx.closePath(); }
function draw() {
  if (!pal || !W) return;
  const e = morph;
  heights(e);
  setCam(e);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  const g = 0.16;
  for (const x of cells) x.depth = rawProj(x.c + 0.5, x.r + 0.5, 0)[2];
  const order = cells.slice().sort((a, b) => a.depth - b.depth);
  // faces: +Y (front), +X / -X (side) depending on yaw
  const faceX = cam.sy > 0 ? 1 : -1;
  const showSide = Math.abs(cam.sy) > 0.01 && cam.sp > 0.01;
  for (const x of order) {
    const X0 = x.c + g / 2, X1 = x.c + 1 - g / 2, Y0 = x.r + g / 2, Y1 = x.r + 1 - g / 2;
    const h = x.h;
    const top = [proj(X0, Y0, h), proj(X1, Y0, h), proj(X1, Y1, h), proj(X0, Y1, h)];
    x.poly = top;
    const isHot = x === hot || x === cursor;
    if (x.future) {
      quad(top);
      ctx.strokeStyle = css(pal.ink, 1, 0.1);
      ctx.lineWidth = 0.8;
      ctx.stroke();
      continue;
    }
    const base = x.km > 0 ? ramp(x.km) : pal.rest;
    if (h > 0.05 && cam.sp > 0.01) {
      if (cam.cy > 0) {
        quad([proj(X0, Y1, 0), proj(X1, Y1, 0), proj(X1, Y1, h), proj(X0, Y1, h)]);
        ctx.fillStyle = css(base, 0.8);
        ctx.fill();
      }
      if (showSide) {
        const XX = faceX > 0 ? X1 : X0;
        quad([proj(XX, Y0, 0), proj(XX, Y1, 0), proj(XX, Y1, h), proj(XX, Y0, h)]);
        ctx.fillStyle = css(base, 0.66);
        ctx.fill();
      }
    }
    quad(top);
    ctx.fillStyle = css(base, isHot ? 1.08 : 1);
    ctx.fill();
    if (isHot) { ctx.strokeStyle = css(pal.ink, 1, 0.9); ctx.lineWidth = 1.4; ctx.stroke(); }
