      const c = proj(x.c + 0.5, x.r + 0.5, h);
      const ph = calm ? 0.5 : (t * 0.65) % 1;
      ctx.strokeStyle = css(pal.hi, 1, (1 - ph) * 0.8);
      ctx.lineWidth = 1.3;
      ctx.beginPath(); ctx.arc(c[0], c[1], 3 + ph * 11, 0, 6.283); ctx.stroke();
