  ctx.font = '600 9px ui-monospace, Menlo, monospace';
  ctx.textBaseline = 'alphabetic';
  ctx.textAlign = 'left';
  // on the far edge while flat, on the near edge once the city stands up
  for (const [Y, a, base] of [[-0.35, 1 - e, 'alphabetic'], [7.25, e, 'top']]) {
    if (a < 0.02) continue;
    ctx.textBaseline = base;
    ctx.fillStyle = css(pal.muted, 1, 0.95 * a);
    for (let m = 0; m < 12; m++) {
      const d = Math.round((Date.UTC(2026, m, 1) - START) / DAY);
