    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = css(pal.muted, 1, 0.9 * (1 - e));
    for (const r of [0, 2, 4, 6]) { const p = proj(-0.3, r + 0.5, 0); ctx.fillText(WD[r][0], p[0], p[1]); }
