  if (x && !x.today) {
    read.setAttribute('data-past', '');
    if (x.future) readText.append(dateOf(x), ' · planned, Harbourline Marathon on Sun 18 Oct');
    else readText.append(b(dateOf(x)), ' · ' + fmt1.format(x.km) + ' km ' + kindOf(x),
      x === longest ? ' · longest of the year' : '');
