    const c = pick(x, y);
    cursor = c && c !== cursor ? c : null;
    fillTip(hot || cursor);
    writeRead();
  }
  drag = null;
  stage.removeAttribute('data-drag');
  idleAt = performance.now();
  kick();
}
stage.addEventListener('pointerup', up);
stage.addEventListener('pointercancel', up);
stage.addEventListener('pointerleave', () => setHot(null));

/* ── keyboard: days and weeks ── */
const byD = new Map(cells.map((x) => [x.d, x]));
stage.addEventListener('keydown', (e) => {
  const k = e.key;
  let d = cursor ? cursor.d : TODAY;
  if (k === 'ArrowRight') d += 7;
  else if (k === 'ArrowLeft') d -= 7;
  else if (k === 'ArrowDown') d += 1;
  else if (k === 'ArrowUp') d -= 1;
  else if (k === 'Home') d = cells[0].d;
  else if (k === 'End') d = TODAY;
  else if (k === 'Escape') { if (!cursor) return; cursor = null; fillTip(hot); writeRead(); e.preventDefault(); kick(); return; }
  else return;
  e.preventDefault();
  const next = byD.get(d);
  if (!next) return;
  cursor = next;
  if (calm) winC = cursor.c;
  fillTip(hot || cursor);
  writeRead();
  idleAt = performance.now();
  kick();
});

/* ── lifecycle ── */
function size() {
  const r = stage.getBoundingClientRect();
  const w = Math.round(r.width), h = Math.round(r.height);
  if (!w || !h || (w === W && h === H)) return false;
  W = w; H = h;
  dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr);
  cv.height = Math.round(H * dpr);
  return true;
}
function onVis() {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) { last = 0; kick(); }
}
document.addEventListener('visibilitychange', onVis);
function onMotion() {
  if (!root.isConnected) { mq.removeEventListener('change', onMotion); return; }
  calm = mq.matches;
  if (calm) { live = TODAY_KM; todayCell.km = live; stats(); writeRead(); drift = 0; }
  kick();
}
mq.addEventListener('change', onMotion);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  if (size()) { theme(); draw(); }
});
ro.observe(stage);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  seen = entries[entries.length - 1].isIntersecting;
  if (seen) { last = 0; kick(); }
});
io.observe(root);

winC = todayCell.c - 6;
theme();
size();
writeRead(true);
stage.setAttribute('data-orbit', '');
if (calm) { morph = 1; draw(); }
else {
  // entry: the flat calendar folds up into the skyline
  draw();
  mFrom = 0; mTo = 1; mT0 = performance.now() + 450;
  kick();
}

css:
.fxa-sankey {
  /* Re-theme with ground and text; the five source inks carry the particles. */
  --fxa-sankey-ground: oklch(0.19 0.02 212);
  --fxa-sankey-text: oklch(0.95 0.01 200);
  --fxa-sankey-wind: oklch(0.8 0.09 182);
  --fxa-sankey-solar: oklch(0.87 0.15 93);
  --fxa-sankey-tidal: oklch(0.68 0.12 240);
  --fxa-sankey-diesel: oklch(0.66 0.06 52);
  --fxa-sankey-cable: oklch(0.74 0.1 325);
  --fxa-sankey-battery: oklch(0.78 0.14 145);
  --fxa-sankey-loss: oklch(0.64 0.14 26);

  --fxa-sankey-muted: color-mix(in oklch, var(--fxa-sankey-text) 56%, var(--fxa-sankey-ground));
  --fxa-sankey-line: color-mix(in oklch, var(--fxa-sankey-text) 12%, transparent);
  --fxa-sankey-raise: color-mix(in oklch, var(--fxa-sankey-text) 7%, var(--fxa-sankey-ground));
  --fxa-sankey-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-sankey-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 0.96;
  min-block-size: 330px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-sankey-text);
  background:
    radial-gradient(80% 60% at 20% 45%, color-mix(in oklch, var(--fxa-sankey-ground) 85%, var(--fxa-sankey-wind)) 0%, transparent 70%),
    var(--fxa-sankey-ground);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-sankey-line);

  & .fxa-sankey__body {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-areas:
      "head switch"
      "stage stage"
      "read read";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto minmax(0, 1fr) auto;
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
  }

  & .fxa-sankey__head { grid-area: head; min-inline-size: 0; }
  & .fxa-sankey__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-sankey-muted);
  }
  & .fxa-sankey__title {
    margin: 5px 0 0;
    font-size: clamp(18px, 5.8cqi, 26px);
    font-weight: 300;
    line-height: 1.05;
    letter-spacing: -0.02em;
    text-wrap: balance;
    & [data-k="total"] { font-weight: 700; font-variant-numeric: tabular-nums; }
  }

  & .fxa-sankey__switch {
    grid-area: switch;
    align-self: start;
    position: relative;
    display: inline-grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    padding: 3px;
    border-radius: 9px;
    background: var(--fxa-sankey-raise);
    box-shadow: inset 0 0 0 1px var(--fxa-sankey-line);
    & button {
      appearance: none;
      position: relative;
      z-index: 1;
      margin: 0;
      border: 0;
      padding: 6px 9px;
      border-radius: 6px;
      background: transparent;
      color: var(--fxa-sankey-muted);
      font: 650 10.5px/1 ui-monospace, Menlo, monospace;
      white-space: nowrap;
      cursor: pointer;
      transition: color 0.2s linear;
    }
    & button:hover { color: var(--fxa-sankey-text); }
    & button[aria-checked="true"] { color: var(--fxa-sankey-ground); }
    & button:focus-visible { outline: 2px solid var(--fxa-sankey-text); outline-offset: 1px; }
    &::before {
      content: "";
      position: absolute;
      inset-block: 3px;
      inset-inline-start: 3px;
      inline-size: calc((100% - 6px) / 2);
      border-radius: 6px;
      background: var(--fxa-sankey-solar);
      transition: translate 0.5s var(--fxa-sankey-spring), background-color 0.5s linear;
    }
    &:has([data-s="1"][aria-checked="true"])::before { translate: 100% 0; background: var(--fxa-sankey-wind); }
  }

  & .fxa-sankey__stage {
    grid-area: stage;
    position: relative;
    min-block-size: 0;
    margin: 10px calc(-1 * clamp(12px, 4cqi, 18px)) 6px;
    outline: none;
    touch-action: pan-y;
  }
  & .fxa-sankey__stage[data-hit] { cursor: pointer; }
  & .fxa-sankey__stage:focus-visible {
    border-radius: 10px;
    box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--fxa-sankey-solar) 70%, transparent);
  }
  & .fxa-sankey__cv { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; display: block; }

  & .fxa-sankey__read {
    grid-area: read;
    display: grid;
    gap: 4px;
    min-block-size: 36px;
    align-content: end;
  }
  & .fxa-sankey__lead {
    margin: 0;
    font: 500 12px/1.3 system-ui, sans-serif;
    color: var(--fxa-sankey-muted);
    font-variant-numeric: tabular-nums;
    & b { font: 700 clamp(15px, 4.6cqi, 19px)/1 ui-monospace, Menlo, monospace; color: var(--fxa-sankey-text); letter-spacing: -0.02em; margin-inline-end: 3px; }
    & i { font-style: normal; font-weight: 650; color: var(--c, var(--fxa-sankey-text)); margin-inline-end: 6px; }
  }
  & .fxa-sankey__line {
    margin: 0;
    display: flex;
    flex-wrap: wrap;
    gap: 3px 12px;
    font: 500 11px/1.25 system-ui, sans-serif;
    color: var(--fxa-sankey-muted);
    font-variant-numeric: tabular-nums;
    & span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
    & i { inline-size: 7px; block-size: 7px; border-radius: 50%; background: var(--c); }
    & b { color: var(--fxa-sankey-text); font-weight: 650; }
  }
}

@container (max-width: 330px) {
  .fxa-sankey .fxa-sankey__long { display: none; }
}
@container (min-width: 600px) {
  .fxa-sankey .fxa-sankey__stage { margin-inline: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .fxa-sankey {
    & .fxa-sankey__switch::before { transition: none; }
  }
}

js:
/* Island grid — a particle Sankey.
   Nodes are stacked per column from a balanced flow table; each link is a band
   between a slice of its source and a slice of its target, drawn as a cubic
   Bezier whose control points share the mid x. A particle owns a lane u in
   [0, 1] across its band and advances at constant horizontal speed (Newton
   inverts x(t)). When it reaches the grid or the battery it picks an outgoing
   link in proportion to flow and keeps its source colour, so every use shows
   its energy mix. Switching day tweens the table; particles keep their lanes. */
const stage = root.querySelector('.fxa-sankey__stage');
const cv = root.querySelector('.fxa-sankey__cv');
const ctx = cv.getContext('2d');
const probe = root.querySelector('.fxa-sankey__probe');
const read = root.querySelector('.fxa-sankey__read');
const lead = root.querySelector('[data-r="lead"]');
const line = root.querySelector('[data-r="line"]');
const outTotal = root.querySelector('[data-k="total"]');
const radios = [...root.querySelectorAll('.fxa-sankey__switch [role="radio"]')];
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const NODES = [
  { id: 'wind', name: 'Wind', col: 0, ink: '--fxa-sankey-wind', renew: true },
  { id: 'solar', name: 'Solar', col: 0, ink: '--fxa-sankey-solar', renew: true },
  { id: 'tidal', name: 'Tidal', col: 0, ink: '--fxa-sankey-tidal', renew: true },
  { id: 'diesel', name: 'Diesel', col: 0, ink: '--fxa-sankey-diesel' },
  { id: 'cable', name: 'Mainland cable', short: 'Cable', col: 0, ink: '--fxa-sankey-cable' },
  { id: 'grid', name: 'Grid', col: 1, ink: '--fxa-sankey-text' },
  { id: 'battery', name: 'Battery', col: 1, ink: '--fxa-sankey-battery' },
  { id: 'homes', name: 'Homes', col: 2, ink: '--fxa-sankey-text' },
  { id: 'desal', name: 'Desalination', short: 'Desal', col: 2, ink: '--fxa-sankey-text' },
  { id: 'harbour', name: 'Harbour & ferries', short: 'Harbour', col: 2, ink: '--fxa-sankey-text' },
  { id: 'fish', name: 'Fish processing', short: 'Fish', col: 2, ink: '--fxa-sankey-text' },
  { id: 'cold', name: 'Cold store', short: 'Cold', col: 2, ink: '--fxa-sankey-text' },
  { id: 'loss', name: 'Losses', col: 2, ink: '--fxa-sankey-loss' },
].map((n, i) => ({ ...n, i, short: n.short || n.name, v: 0, x: 0, y: 0, h: 0, inL: [], outL: [] }));
const ID = Object.fromEntries(NODES.map((n) => [n.id, n]));
// MWh per day. Every node balances: in = out.
const DAYS = [
  { label: '21 June', flows: [
    ['wind', 'grid', 336], ['wind', 'battery', 56], ['solar', 'grid', 214], ['solar', 'battery', 74],
    ['tidal', 'grid', 96], ['diesel', 'grid', 18], ['cable', 'grid', 40],
    ['grid', 'homes', 262], ['grid', 'desal', 168], ['grid', 'harbour', 104], ['grid', 'fish', 88], ['grid', 'cold', 42], ['grid', 'loss', 40],
    ['battery', 'homes', 96], ['battery', 'harbour', 22], ['battery', 'loss', 12]] },
  { label: '21 December', flows: [
    ['wind', 'grid', 448], ['wind', 'battery', 72], ['solar', 'grid', 46], ['solar', 'battery', 18],
    ['tidal', 'grid', 96], ['diesel', 'grid', 168], ['cable', 'grid', 60],
    ['grid', 'homes', 352], ['grid', 'desal', 92], ['grid', 'harbour', 128], ['grid', 'fish', 104], ['grid', 'cold', 46], ['grid', 'loss', 96],
    ['battery', 'homes', 70], ['battery', 'harbour', 12], ['battery', 'loss', 8]] },
];
const LINKS = DAYS[0].flows.map(([a, b], i) => {
  const L = { i, s: ID[a], t: ID[b], v: 0, from: 0, to: 0, acc: 0, ys0: 0, ys1: 0, yt0: 0, yt1: 0 };
  L.s.outL.push(L); L.t.inL.push(L);
  return L;
});
let day = 0;
function values(d) { return DAYS[d].flows.map((f) => f[2]); }
values(0).forEach((v, i) => { LINKS[i].v = v; });

/* ── colour ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const rgba = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + Math.max(0, Math.min(1, a)).toFixed(3) + ')';
let pal = null;
function theme() {
  pal = { ground: rgb('--fxa-sankey-ground'), text: rgb('--fxa-sankey-text'), muted: rgb('--fxa-sankey-muted') };
  for (const n of NODES) n.rgb = rgb(n.ink);
}

/* ── layout ── */
let W = 0, H = 0, dpr = 1;
const NW = 7;
function layout() {
  for (const n of NODES) {
    const vin = n.inL.reduce((s, l) => s + l.v, 0), vout = n.outL.reduce((s, l) => s + l.v, 0);
    n.v = Math.max(vin, vout);
  }
  const padT = 8, padB = 8, gap = Math.max(5, H * 0.028);
  const cols = [0, 1, 2].map((c) => NODES.filter((n) => n.col === c));
  const k = Math.min(...cols.map((c) => (H - padT - padB - gap * (c.length - 1)) / c.reduce((s, n) => s + n.v, 0)));
  const xs = [14, W / 2 - NW / 2, W - 14 - NW];
  cols.forEach((col, c) => {
    const used = col.reduce((s, n) => s + n.v * k, 0) + gap * (col.length - 1);
    let y = padT + (H - padT - padB - used) / 2;
    for (const n of col) { n.x = xs[c]; n.y = y; n.h = n.v * k; y += n.h + gap; }
  });
  for (const n of NODES) {
    let y = n.y;
    for (const l of n.outL.slice().sort((a, b) => a.t.y - b.t.y)) { l.ys0 = y; y += l.v * k; l.ys1 = y; }
    y = n.y;
    for (const l of n.inL.slice().sort((a, b) => a.s.y - b.s.y)) { l.yt0 = y; y += l.v * k; l.yt1 = y; }
  }
}
// x(t) of a Bezier whose inner control points both sit at the mid x
const xfrac = (t) => t * t * t - 1.5 * t * t + 1.5 * t;
function tFor(p) {
  let t = p;
  for (let k = 0; k < 4; k++) t -= (xfrac(t) - p) / (3 * t * t - 3 * t + 1.5);
  return Math.max(0, Math.min(1, t));
}
const smooth = (t) => t * t * (3 - 2 * t);
function band(l) {
  const x0 = l.s.x + NW, x1 = l.t.x, xm = (x0 + x1) / 2;
  ctx.beginPath();
  ctx.moveTo(x0, l.ys0);
  ctx.bezierCurveTo(xm, l.ys0, xm, l.yt0, x1, l.yt0);
  ctx.lineTo(x1, l.yt1);
  ctx.bezierCurveTo(xm, l.yt1, xm, l.ys1, x0, l.ys1);
  ctx.closePath();
}

/* ── particles ── */
const parts = [];
const DUR = 2.3; // seconds to cross one stage
let seed = 7;
const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
function pickOut(n) {
  const tot = n.outL.reduce((s, l) => s + l.v, 0);
  let r = rnd() * tot;
  for (const l of n.outL) { r -= l.v; if (r <= 0) return l; }
  return n.outL[n.outL.length - 1];
}
function total() { return NODES.filter((n) => n.col === 0).reduce((s, n) => s + n.v, 0); }
function step(dt) {
  const budget = Math.round(Math.max(120, Math.min(420, W * 0.9)));
  const rate = budget / (Math.max(1, total()) * 2 * DUR);
  for (const l of LINKS) {
    if (l.s.col !== 0) continue;
    l.acc += l.v * rate * dt;
    while (l.acc >= 1) {
      l.acc -= 1;
      parts.push({ l, p: rnd() * 0.02, u: 0.08 + rnd() * 0.84, src: l.s, sp: 0.9 + rnd() * 0.2, x: -1, y: -1, px: -1, py: -1 });
    }
  }
  for (let k = parts.length - 1; k >= 0; k--) {
    const q = parts[k];
    q.p += (dt / DUR) * q.sp;
    if (q.p >= 1) {
      if (q.l.t.col === 2) { parts.splice(k, 1); continue; }
      q.l = pickOut(q.l.t);
      q.p -= 1;
      q.u = 0.08 + rnd() * 0.84;
      q.hop = true;
    }
  }
}
function place(q) {
  const l = q.l, t = tFor(q.p);
  const x0 = l.s.x + NW, x1 = l.t.x;
  const ys = l.ys0 + (l.ys1 - l.ys0) * q.u, yt = l.yt0 + (l.yt1 - l.yt0) * q.u;
  q.px = q.hop ? -1 : q.x; q.py = q.y;
  q.hop = false;
  q.x = x0 + (x1 - x0) * q.p;
  q.y = ys + (yt - ys) * smooth(t);
}

/* ── focus ── */
let hover = null, cursor = null;
const focus = () => hover || cursor;
function related(f, l) {
  if (!f) return true;
  if (f.kind === 'link') return l === f.l;
  return l.s === f.n || l.t === f.n;
}

/* ── draw ── */
function draw() {
  if (!pal || !W) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  const f = focus();
  for (const l of LINKS) {
    if (l.v <= 0.01) continue;
    band(l);
    const on = related(f, l);
    const g = ctx.createLinearGradient(l.s.x + NW, 0, l.t.x, 0);
    const a = f ? (on ? 0.34 : 0.05) : 0.16;
    g.addColorStop(0, rgba(l.s.rgb, a));
    g.addColorStop(1, rgba(l.t.rgb, a * 0.7));
    ctx.fillStyle = g;
    ctx.fill();
  }
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineCap = 'round';
  for (const q of parts) {
    if (q.x < 0) continue;
    const on = related(f, q.l);
    ctx.strokeStyle = rgba(q.src.rgb, on ? 0.9 : 0.12);
    ctx.lineWidth = on && f ? 2 : 1.6;
    // a streak along the last step; at rest (or after a hop) a short stub pointing downstream
    let dx = 1.5, dy = 0;
    if (q.px >= 0) {
      const ex = q.x - q.px, ey = q.y - q.py;
      if (Math.abs(ex) < 20 && Math.abs(ey) < 20 && ex * ex + ey * ey > 0.4) { dx = ex * 2.6; dy = ey * 2.6; }
    }
    ctx.beginPath();
    ctx.moveTo(q.x - dx, q.y - dy);
    ctx.lineTo(q.x, q.y);
    ctx.stroke();
  }
  ctx.globalCompositeOperation = 'source-over';
  // node bars and labels
  ctx.textBaseline = 'middle';
  for (const n of NODES) {
    if (n.h < 0.5) continue;
    const on = !f || (f.kind === 'node' ? f.n === n || n.inL.concat(n.outL).some((l) => related(f, l)) : f.l.s === n || f.l.t === n);
    ctx.fillStyle = rgba(n.rgb, on ? 1 : 0.35);
    ctx.beginPath();
    ctx.roundRect(n.x, n.y, NW, n.h, 2);
    ctx.fill();
    if (f && f.kind === 'node' && f.n === n) {
      ctx.strokeStyle = rgba(pal.text, 0.95);
      ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.roundRect(n.x - 2.5, n.y - 2.5, NW + 5, n.h + 5, 4); ctx.stroke();
    }
    if (n.h < 9 && n.col !== 1) continue;
    const right = n.col !== 2;
    const tx = right ? n.x + NW + 6 : n.x - 6;
    const ty = n.y + n.h / 2;
    ctx.textAlign = right ? 'left' : 'right';
    const label = n.col === 1 ? n.name : n.short;
    ctx.font = '650 10.5px system-ui, sans-serif';
    ctx.lineJoin = 'round';
    ctx.lineWidth = 3;
    ctx.strokeStyle = rgba(pal.ground, 0.85);
    const val = String(Math.round(n.v));
    if (n.col === 1) {
      // grid and battery: name above the bar's middle, value below
      ctx.strokeText(label, tx, ty - 6); ctx.fillStyle = rgba(pal.text, on ? 1 : 0.4); ctx.fillText(label, tx, ty - 6);
      ctx.font = '600 9.5px ui-monospace, Menlo, monospace';
      ctx.strokeText(val, tx, ty + 6); ctx.fillStyle = rgba(pal.muted, on ? 1 : 0.4); ctx.fillText(val, tx, ty + 6);
      continue;
    }
    const lw = ctx.measureText(label).width;
    ctx.strokeText(label, tx, ty); ctx.fillStyle = rgba(pal.text, on ? 1 : 0.4); ctx.fillText(label, tx, ty);
    ctx.font = '600 9.5px ui-monospace, Menlo, monospace';
    const vx = right ? tx + lw + 5 : tx - lw - 5;
    ctx.strokeText(val, vx, ty); ctx.fillStyle = rgba(pal.muted, on ? 1 : 0.4); ctx.fillText(val, vx, ty);
  }
}

/* ── readout ── */
const fmt = new Intl.NumberFormat('en-GB');
function el(tag, text) { const e = document.createElement(tag); if (text != null) e.textContent = text; return e; }
function named(n) { const e = el('i', n.name); e.style.setProperty('--c', 'var(' + n.ink + ')'); return e; }
function dot(n, parts) {
  const s = el('span'), i = el('i');
  i.style.setProperty('--c', 'var(' + n.ink + ')');
  s.append(i, ...parts);
  return s;
}
function writeRead() {
  const f = focus();
  const tot = total();
  lead.textContent = ''; line.textContent = '';
  const renew = NODES.filter((n) => n.renew).reduce((s, n) => s + n.v, 0);
  if (!f) {
    lead.append(el('b', Math.round((renew / tot) * 100) + '%'), 'renewable on ' + DAYS[day].label);
    const srcs = NODES.filter((n) => n.col === 0).sort((a, b) => b.v - a.v).slice(0, 3);
    line.append(...srcs.map((n) => dot(n, [n.short + ' ', el('b', fmt.format(Math.round(n.v)))])));
    return;
  }
  if (f.kind === 'link') {
    const l = f.l;
    lead.append(el('b', fmt.format(Math.round(l.v))), 'MWh ', named(l.s), '→ ', named(l.t));
    line.append(el('span', Math.round((l.v / l.s.v) * 100) + '% of ' + l.s.short + '’s output'),
      el('span', Math.round((l.v / l.t.v) * 100) + '% of ' + l.t.short + '’s intake'));
    return;
  }
  const n = f.n;
  lead.append(named(n), el('b', fmt.format(Math.round(n.v))), 'MWh · ' + Math.round((n.v / tot) * 100) + '% of the day');
  const ls = n.col === 2 ? n.inL : n.outL;
  line.append(...ls.filter((l) => l.v > 0.5).sort((a, b) => b.v - a.v).slice(0, 3).map((l) => {
    const o = n.col === 2 ? l.s : l.t;
    return dot(o, [(n.col === 2 ? 'from ' : 'to ') + o.short + ' ', el('b', fmt.format(Math.round(l.v)))]);
  }));
}

/* ── loop ── */
let raf = 0, last = 0, seen = true, tw = null;
function kick() { if (!raf && seen && !document.hidden && root.isConnected) raf = requestAnimationFrame(frame); }
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
  last = now;
  if (tw) {
    const p = Math.min(1, (now - tw.t0) / tw.dur);
    const e = p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2;
    for (const l of LINKS) l.v = l.from + (l.to - l.from) * e;
    if (p >= 1) { tw = null; for (const l of LINKS) l.v = l.to; writeRead(); }
    layout();
    outTotal.textContent = fmt.format(Math.round(total()));
  }
  if (!calm) step(dt);
  for (const q of parts) place(q);
  draw();
  if (!calm || tw) kick(); else last = 0;
}
function setDay(d, focusIt) {
  radios.forEach((b) => {
    const on = +b.dataset.s === d;
    b.setAttribute('aria-checked', String(on));
    b.tabIndex = on ? 0 : -1;
    if (on && focusIt) b.focus();
  });
  if (d === day) return;
  day = d;
  const vs = values(d);
  LINKS.forEach((l, i) => { l.from = l.v; l.to = vs[i]; });
  if (calm) {
    LINKS.forEach((l) => { l.v = l.to; });
    layout(); prewarm(); writeRead(); outTotal.textContent = fmt.format(total()); draw();
    return;
  }
  tw = { t0: performance.now(), dur: 1100 };
  kick();
}
radios.forEach((b, i) => {
  b.addEventListener('click', () => setDay(+b.dataset.s, false));
  b.addEventListener('keydown', (e) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    setDay(+radios[(i + 1) % 2].dataset.s, true);
  });
});
function prewarm() {
  // run the river for a while so the first frame is already full
  parts.length = 0;
  for (const l of LINKS) l.acc = 0;
  for (let k = 0; k < 160; k++) step(1 / 30);
  for (const q of parts) { place(q); q.px = -1; }
}

/* ── pointer ── */
function local(e) { const r = stage.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }
function hitTest(x, y) {
  for (const n of NODES) if (x >= n.x - 4 && x <= n.x + NW + 4 && y >= n.y - 2 && y <= n.y + n.h + 2) return { kind: 'node', n };
  for (const l of LINKS) {
    const x0 = l.s.x + NW, x1 = l.t.x;
    if (x < x0 || x > x1 || l.v < 0.5) continue;
    const t = tFor((x - x0) / (x1 - x0)), s = smooth(t);
    const top = l.ys0 + (l.yt0 - l.ys0) * s, bot = l.ys1 + (l.yt1 - l.ys1) * s;
    if (y >= top && y <= bot) return { kind: 'link', l };
  }
  return null;
}
const same = (a, b) => (!a && !b) || (a && b && a.kind === b.kind && a.n === b.n && a.l === b.l);
stage.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch') return;
  const h = hitTest(...local(e));
  stage.toggleAttribute('data-hit', !!h);
  if (!same(h, hover)) { hover = h; writeRead(); if (calm) draw(); }
});
stage.addEventListener('pointerleave', () => { if (hover) { hover = null; writeRead(); if (calm) draw(); } });
stage.addEventListener('click', (e) => {
  const h = hitTest(...local(e));
  cursor = h && !same(h, cursor) ? h : null;
  writeRead();
  if (calm) draw();
});

/* ── keyboard: up/down within a column, left/right across ── */
stage.addEventListener('keydown', (e) => {
  const cur = cursor && cursor.kind === 'node' ? cursor.n : null;
  let next = null;
  const col = (c) => NODES.filter((n) => n.col === c);
  if (!cur && ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) next = NODES[0];
  else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    const c = col(cur.col), i = c.indexOf(cur);
    next = c[(i + (e.key === 'ArrowDown' ? 1 : c.length - 1)) % c.length];
  } else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
    const nc = cur.col + (e.key === 'ArrowRight' ? 1 : -1);
    if (nc < 0 || nc > 2) return;
    // land on the most connected node in the next column
    const links = e.key === 'ArrowRight' ? cur.outL : cur.inL;
    const best = links.slice().sort((a, b) => b.v - a.v)[0];
    next = best ? (e.key === 'ArrowRight' ? best.t : best.s) : col(nc)[0];
  } else if (e.key === 'Escape') {
    if (!cursor) return;
    cursor = null;
  } else return;
  e.preventDefault();
  if (next) cursor = { kind: 'node', n: next };
  writeRead();
  if (calm) draw();
});

/* ── lifecycle ── */
function size() {
  const r = stage.getBoundingClientRect();
  const w = Math.round(r.width), h = Math.round(r.height);
  if (!w || !h || (w === W && h === H)) return false;
  W = w; H = h;
  dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr);
  cv.height = Math.round(H * dpr);
  layout();
  return true;
}
function onVis() {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) { last = 0; kick(); }
}
document.addEventListener('visibilitychange', onVis);
function onMotion() {
  if (!root.isConnected) { mq.removeEventListener('change', onMotion); return; }
  calm = mq.matches;
  kick();
}
mq.addEventListener('change', onMotion);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  if (size()) { theme(); for (const q of parts) { place(q); q.px = -1; } draw(); }
});
ro.observe(stage);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); mq.removeEventListener('change', onMotion); return; }
  seen = entries[entries.length - 1].isIntersecting;
  if (seen) { last = 0; kick(); }
});
io.observe(root);

theme();
size();
outTotal.textContent = fmt.format(total());
prewarm();
writeRead();
draw();
kick();

css:
.fxa-hive {
  /* Re-theme with paper, ink and the two ends of the traffic ramp. */
  --fxa-hive-paper: oklch(0.968 0.02 92);
  --fxa-hive-ink: oklch(0.27 0.035 60);
  --fxa-hive-lo: oklch(0.9 0.08 92);
  --fxa-hive-hi: oklch(0.58 0.15 55);

  --fxa-hive-muted: color-mix(in oklch, var(--fxa-hive-ink) 58%, var(--fxa-hive-paper));
  --fxa-hive-line: color-mix(in oklch, var(--fxa-hive-ink) 12%, transparent);
  --fxa-hive-night: color-mix(in oklch, var(--fxa-hive-ink) 14%, var(--fxa-hive-paper));
  --fxa-hive-comb: color-mix(in oklch, var(--fxa-hive-lo) 40%, var(--fxa-hive-paper));
  --fxa-hive-out: cubic-bezier(.16, 1, .3, 1);
  --fxa-hive-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 1.04;
  min-block-size: 340px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxa-hive-ink);
  background:
    radial-gradient(65% 55% at 50% 55%, var(--fxa-hive-comb) 0%, transparent 70%),
    var(--fxa-hive-paper);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxa-hive-line);

  & .fxa-hive__body {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-areas:
      "head stats"
      "dial dial"
      "foot foot";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto minmax(0, 1fr) auto;
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
  }

  & .fxa-hive__head { grid-area: head; min-inline-size: 0; }
  & .fxa-hive__eyebrow {
    margin: 0;
    font: 600 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--fxa-hive-muted);
    text-wrap: balance;
  }
  & .fxa-hive__title {
    margin: 5px 0 0;
    font-family: ui-serif, Georgia, "Times New Roman", serif;
    font-size: clamp(21px, 7cqi, 30px);
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.02em;
    text-wrap: balance;
  }

  & .fxa-hive__stats { grid-area: stats; display: flex; gap: clamp(10px, 3.4cqi, 16px); margin: 0; align-self: start; }
  & .fxa-hive__stat {
    display: grid;
    justify-items: end;
    gap: 3px;
    transition: opacity 0.5s var(--fxa-hive-out), translate 0.7s var(--fxa-hive-spring);
    transition-delay: calc(var(--i) * 60ms + 140ms);
    @starting-style { opacity: 0; translate: 0 6px; }
  }
  & .fxa-hive__stat dt {
    font: 600 9.5px/1 system-ui, sans-serif;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--fxa-hive-muted);
    white-space: nowrap;
    & span { font-family: ui-monospace, Menlo, monospace; letter-spacing: 0; }
  }
  & .fxa-hive__stat dd {
    margin: 0;
    font: 650 clamp(15px, 4.8cqi, 20px)/1 ui-monospace, Menlo, monospace;
    letter-spacing: -0.03em;
    font-variant-numeric: tabular-nums;
  }

  & .fxa-hive__dial {
    grid-area: dial;
    position: relative;
    min-block-size: 0;
    margin-block: 6px 4px;
    container-type: size;
  }
  & .fxa-hive__svg {
    position: absolute;
    left: 50%;
    top: 50%;
    inline-size: 100cqmin;
    block-size: 100cqmin;
    translate: -50% -50%;
    display: block;
    overflow: visible;
    outline: none;
    cursor: pointer;
    touch-action: none;
  }
  & .fxa-hive__svg:focus-visible .fxa-hive__disc { stroke: var(--fxa-hive-hi); stroke-width: 1.4; }
  & .fxa-hive__disc { fill: color-mix(in oklch, var(--fxa-hive-paper) 70%, transparent); stroke: var(--fxa-hive-line); stroke-width: 0.6; }

  & .fxa-hive__ticks line { stroke: color-mix(in oklch, var(--fxa-hive-ink) 28%, transparent); stroke-width: 0.6; stroke-linecap: round; }
  & .fxa-hive__ticks line.is-major { stroke: var(--fxa-hive-ink); stroke-width: 0.9; }
  & .fxa-hive__ticks text {
    font: 600 6.4px/1 ui-monospace, Menlo, monospace;
    fill: var(--fxa-hive-muted);
    text-anchor: middle;
    dominant-baseline: central;
  }

  & .fxa-hive__night { fill: none; stroke: var(--fxa-hive-night); stroke-width: 2.4; }
  & .fxa-hive__day { fill: none; stroke: var(--fxa-hive-lo); stroke-width: 2.4; stroke-linecap: round; }

  & .fxa-hive__ghosts line {
    stroke: color-mix(in oklch, var(--fxa-hive-ink) 9%, transparent);
    stroke-width: 1.3;
    stroke-linecap: round;
  }
  & .fxa-hive__bar {
    stroke: color-mix(in oklch, var(--fxa-hive-hi) var(--k, 50%), var(--fxa-hive-lo));
    stroke-width: 1.35;
    stroke-linecap: round;
    stroke-dasharray: 1 1;
    stroke-dashoffset: 1;
    transition: stroke-dashoffset 0.7s var(--fxa-hive-spring), stroke 0.2s linear;
  }
  & .fxa-hive__bar.is-past {
    stroke-dashoffset: 0;
    @starting-style { stroke-dashoffset: 1; }
  }
  & .fxa-hive__bar.is-hot { stroke: var(--fxa-hive-ink); }
  & .fxa-hive__bars.is-reset .fxa-hive__bar {
    transition: stroke-dashoffset 0.45s var(--fxa-hive-out);
    transition-delay: calc(var(--i) * 3ms);
  }

  & .fxa-hive__marks path { fill: none; stroke: var(--fxa-hive-ink); stroke-width: 0.7; stroke-dasharray: 1.4 1.4; }
  & .fxa-hive__marks text {
    font: italic 500 6px/1 ui-serif, Georgia, serif;
    fill: var(--fxa-hive-ink);
    text-anchor: middle;
    dominant-baseline: central;
  }

  & .fxa-hive__hand {
    pointer-events: none;
    & line { stroke: var(--fxa-hive-ink); stroke-width: 1.1; stroke-linecap: round; }
    & circle { fill: var(--fxa-hive-paper); stroke: var(--fxa-hive-ink); stroke-width: 1.2; }
  }

  & .fxa-hive__core {
    position: absolute;
    left: 50%;
    top: 50%;
    translate: -50% -50%;
    inline-size: 34cqmin;
    block-size: 34cqmin;
    border-radius: 50%;
    display: grid;
    place-content: center;
    justify-items: center;
    gap: 0.9cqmin;
    pointer-events: none;
    text-align: center;
    background: radial-gradient(circle, var(--fxa-hive-paper) 62%, color-mix(in oklch, var(--fxa-hive-paper) 0%, transparent) 72%);
  }
  & .fxa-hive__time {
    font: 700 max(15px, 8.2cqmin)/1 ui-monospace, Menlo, monospace;
    letter-spacing: -0.04em;
    font-variant-numeric: tabular-nums;
  }
  & .fxa-hive__rate {
    font: 500 max(9.5px, 3.6cqmin)/1.1 system-ui, sans-serif;
    color: var(--fxa-hive-muted);
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxa-hive-hi); font-weight: 750; }
  }
  & .fxa-hive__state {
    font: italic 500 max(9px, 3.4cqmin)/1.1 ui-serif, Georgia, serif;
    color: var(--fxa-hive-ink);
    max-inline-size: 26cqmin;
    text-wrap: balance;
  }

  & .fxa-hive__foot {
    grid-area: foot;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  & .fxa-hive__play {
    appearance: none;
    flex: none;
    margin: 0;
    border: 0;
    display: grid;
    place-items: center;
    inline-size: 30px;
    block-size: 30px;
    border-radius: 50%;
    background: var(--fxa-hive-ink);
    color: var(--fxa-hive-paper);
    cursor: pointer;
    transition: scale 0.35s var(--fxa-hive-spring), background-color 0.2s linear;
    & svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    & .fxa-hive__ico-play { display: none; fill: currentColor; stroke: none; }
  }
  & .fxa-hive__play[aria-pressed="false"] {
    & .fxa-hive__ico-pause { display: none; }
    & .fxa-hive__ico-play { display: inline; }
  }
  & .fxa-hive__play:hover { background: color-mix(in oklch, var(--fxa-hive-ink) 85%, var(--fxa-hive-hi)); }
  & .fxa-hive__play:active { scale: 0.92; }
  & .fxa-hive__play:focus-visible { outline: 2px solid var(--fxa-hive-hi); outline-offset: 2px; }
  & .fxa-hive__note {
    flex: 1;
    min-inline-size: 0;
    margin: 0;
    font: 500 11px/1.25 system-ui, sans-serif;
    color: var(--fxa-hive-muted);
    text-wrap: pretty;
  }
  & .fxa-hive__legend {
    margin: 0;
    display: flex;
    align-items: center;
    gap: 5px;
    font: 600 9.5px/1 ui-monospace, Menlo, monospace;
    color: var(--fxa-hive-muted);
    & i { inline-size: clamp(36px, 12cqi, 60px); block-size: 6px; border-radius: 3px; background: linear-gradient(90deg in oklch, var(--fxa-hive-lo), var(--fxa-hive-hi)); }
  }

  & .fxa-hive__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@container (max-width: 340px) {
  .fxa-hive .fxa-hive__legend { display: none; }
  .fxa-hive .fxa-hive__stat:nth-child(2) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .fxa-hive {
    & .fxa-hive__stat,
    & .fxa-hive__bar,
    & .fxa-hive__bars.is-reset .fxa-hive__bar,
    & .fxa-hive__play { transition: none; }
  }
}

js:
/* Hive clock — a radial 24-hour clock of entrance traffic.
   144 ten-minute bins radiate from midnight at twelve o'clock. Each petal is an
   SVG line with pathLength 1, revealed by stroke-dashoffset as the hand sweeps
   past; the ghost behind it keeps the whole day's silhouette visible. The dial
   is a slider: drag or click to scrub, arrow keys step ten minutes, Space plays
   and pauses. At midnight the petals retract in a clockwise wave. */
const NS = 'http://www.w3.org/2000/svg';
const svg = root.querySelector('.fxa-hive__svg');
const gTicks = root.querySelector('.fxa-hive__ticks');
const gGhost = root.querySelector('.fxa-hive__ghosts');
const gBars = root.querySelector('.fxa-hive__bars');
const gMarks = root.querySelector('.fxa-hive__marks');
const hand = root.querySelector('.fxa-hive__hand');
const dayArc = root.querySelector('.fxa-hive__day');
const nightArc = root.querySelector('.fxa-hive__night');
const playBtn = root.querySelector('.fxa-hive__play');
const live = root.querySelector('.fxa-hive__sr');
const C = (k) => root.querySelector('[data-c="' + k + '"]');
const K = (k) => root.querySelector('[data-k="' + k + '"]');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

/* ── data: bees per minute through the entrance, ten-minute means ── */
const BINS = 144, SUNRISE = 4 * 60 + 43, SUNSET = 21 * 60 + 21;
const RAIN0 = 15 * 60 + 10, RAIN1 = 15 * 60 + 50;
let seed = 1806;
const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
const g = (m, mu, s) => Math.exp(-((m - mu) * (m - mu)) / (2 * s * s));
const RATE = Array.from({ length: BINS }, (_, i) => {
  const m = i * 10 + 5;
  const a = SUNRISE - 20, b = SUNSET + 25;
  if (m < a || m > b) return Math.round(rnd() * 2);
  const day = Math.sin((Math.PI * (m - a)) / (b - a));
  let v = 440 * Math.pow(day, 1.6) * (1 + 0.12 * g(m, 760, 60)) + 35 * g(m, 860, 18);
  if (m >= RAIN0 && m < RAIN1) v *= 0.08;
  else if (m >= RAIN1 && m < RAIN1 + 40) v *= 0.55 + ((m - RAIN1) / 40) * 0.45;
  return Math.max(0, Math.round(v * (0.94 + rnd() * 0.12)));
});
const TOTAL = RATE.reduce((s, v) => s + v * 10, 0);
const PEAK = RATE.indexOf(Math.max(...RATE));
const VMAX = Math.ceil(RATE[PEAK] / 50) * 50;
const hhmm = (min) => String(Math.floor(min / 60) % 24).padStart(2, '0') + ':' + String(Math.round(min % 60)).padStart(2, '0');
K('total').textContent = new Intl.NumberFormat('en-GB').format(TOTAL);
K('peak').textContent = RATE[PEAK] + '/min';
K('peakat').textContent = hhmm(PEAK * 10);
K('max').textContent = VMAX;
function state(i) {
  const m = i * 10 + 5, v = RATE[i];
  if (m >= RAIN0 && m < RAIN1) return 'Rain shower';
  if (v < 6) return m < 720 ? 'Hive asleep' : 'Everyone home';
  if (m < 9 * 60) return 'First foragers';
  if (m >= 13 * 60 + 50 && m < 15 * 60) return 'Orientation flights';
  if (m > 19 * 60) return 'Heading home';
  return v > 0.8 * RATE[PEAK] ? 'Peak foraging' : 'Foraging';
}

/* ── geometry, in viewBox units ── */
const R0 = 40, RMAX = 84, TAU = Math.PI * 2;
// noon at twelve o'clock, so the busy half of the day blooms upward
const ang = (min) => (min / 1440) * TAU + Math.PI;
const at = (r, a) => [Math.sin(a) * r, -Math.cos(a) * r];
function el(tag, attrs) {
  const e = document.createElementNS(NS, tag);
  for (const k in attrs) e.setAttribute(k, attrs[k]);
  return e;
}
for (let h = 0; h < 24; h++) {
  const a = ang(h * 60), major = h % 6 === 0;
  const [x1, y1] = at(major ? 87 : 88.5, a), [x2, y2] = at(91, a);
  gTicks.append(el('line', { x1, y1, x2, y2, class: major ? 'is-major' : '' }));
  if (major) {
    const [tx, ty] = at(95.5, a);
    const t = el('text', { x: tx, y: ty });
    t.textContent = String(h).padStart(2, '0');
    gTicks.append(t);
  }
}
function arcD(r, a0, a1) {
  const [x0, y0] = at(r, a0), [x1, y1] = at(r, a1);
  return 'M' + x0.toFixed(2) + ' ' + y0.toFixed(2) + 'A' + r + ' ' + r + ' 0 ' + (a1 - a0 > Math.PI ? 1 : 0) + ' 1 ' + x1.toFixed(2) + ' ' + y1.toFixed(2);
}
nightArc.setAttribute('d', arcD(35.5, ang(SUNSET), ang(SUNRISE) + TAU));
dayArc.setAttribute('d', arcD(35.5, ang(SUNRISE), ang(SUNSET)));
gMarks.append(el('path', { d: arcD(87, ang(RAIN0), ang(RAIN1)) }));
{
  const mid = ang((RAIN0 + RAIN1) / 2), [x, y] = at(80, mid);
  const deg = ((mid * 180) / Math.PI) % 360;
  const t = el('text', { x: x.toFixed(2), y: y.toFixed(2), transform: 'rotate(' + (deg > 90 && deg < 270 ? deg - 180 : deg).toFixed(1) + ' ' + x.toFixed(2) + ' ' + y.toFixed(2) + ')' });
  t.textContent = 'shower';
  gMarks.append(t);
}
const bars = RATE.map((v, i) => {
  const a = ang(i * 10 + 5);
  const len = 1.5 + (RMAX - R0 - 2) * (v / VMAX);
  const [x1, y1] = at(R0 + 2, a), [x2, y2] = at(R0 + 2 + len, a);
  const p = { x1: x1.toFixed(2), y1: y1.toFixed(2), x2: x2.toFixed(2), y2: y2.toFixed(2) };
  gGhost.append(el('line', p));
  const b = el('line', { ...p, pathLength: 1, class: 'fxa-hive__bar' });
  b.style.setProperty('--k', Math.round(Math.pow(v / VMAX, 0.8) * 100) + '%');
  b.style.setProperty('--i', i);
  gBars.append(b);
