});

/* ── state ── */
let minute = 14 * 60 + 20, playing = !calm, shown = -1, hot = -1;
const SPEED = 1440 / 72; // minutes of hive time per second
function paintBars(bin, wrapped) {
  if (wrapped && !calm) {
    gBars.classList.add('is-reset');
    bars.forEach((b) => b.classList.remove('is-past'));
    setTimeout(() => { if (root.isConnected) gBars.classList.remove('is-reset'); }, 900);
  } else {
    bars.forEach((b, i) => b.classList.toggle('is-past', i <= bin));
  }
}
function readout(i) {
  C('time').textContent = hhmm(i * 10);
  C('rate').textContent = RATE[i];
  C('state').textContent = state(i);
}
function setMinute(m, announce) {
  const prev = minute;
  minute = ((m % 1440) + 1440) % 1440;
  hand.setAttribute('transform', 'rotate(' + ((minute / 1440) * 360 + 180).toFixed(2) + ')');
  const bin = Math.floor(minute / 10);
  if (bin !== shown) {
    const wrapped = shown >= 0 && minute < prev && prev - minute > 720;
    shown = bin;
    paintBars(bin, wrapped);
    if (hot < 0) readout(bin);
    svg.setAttribute('aria-valuenow', bin * 10);
    svg.setAttribute('aria-valuetext', hhmm(bin * 10) + ', ' + RATE[bin] + ' bees per minute, ' + state(bin));
    if (announce) live.textContent = hhmm(bin * 10) + ', ' + RATE[bin] + ' bees per minute. ' + state(bin) + '.';
  }
}
function setPlaying(on) {
  playing = on;
  playBtn.setAttribute('aria-pressed', String(on));
  playBtn.setAttribute('aria-label', on ? 'Pause the replay' : 'Play the replay');
  if (on) { last = 0; kick(); }
}

/* ── loop ── */
let raf = 0, last = 0, seen = true;
function kick() { if (!raf && seen && !document.hidden && root.isConnected && playing) raf = requestAnimationFrame(frame); }
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
  last = now;
  if (playing && !drag) setMinute(minute + dt * SPEED, false);
  kick();
}

/* ── pointer: hover previews a bin, press and drag scrubs the hand ── */
let drag = null, resume = false;
function minuteAt(e) {
  const r = svg.getBoundingClientRect();
  const x = e.clientX - (r.left + r.width / 2), y = e.clientY - (r.top + r.height / 2);
  let a = Math.atan2(x, -y) - Math.PI;
  if (a < 0) a += TAU;
  return { m: (a / TAU) * 1440, d: Math.hypot(x, y) / (r.width / 2) * 100 };
}
function setHot(i) {
  if (i === hot) return;
  if (hot >= 0) bars[hot].classList.remove('is-hot');
  hot = i;
  if (hot >= 0) { bars[hot].classList.add('is-hot'); readout(hot); }
  else readout(shown);
}
svg.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const p = minuteAt(e);
  if (p.d < R0 * 0.6) return;
  drag = { id: e.pointerId };
  resume = playing;
  if (playing) setPlaying(false);
  svg.setPointerCapture(e.pointerId);
  setHot(-1);
  setMinute(p.m, false);
  e.preventDefault();
  svg.focus({ preventScroll: true });
});
svg.addEventListener('pointermove', (e) => {
  const p = minuteAt(e);
  if (drag && e.pointerId === drag.id) { setMinute(p.m, false); return; }
  if (e.pointerType === 'touch') return;
  setHot(p.d > R0 && p.d < 92 ? Math.floor(p.m / 10) : -1);
});
function up(e) {
  if (!drag || e.pointerId !== drag.id) return;
  drag = null;
  live.textContent = hhmm(shown * 10) + ', ' + RATE[shown] + ' bees per minute. ' + state(shown) + '.';
  if (resume) setPlaying(true);
}
svg.addEventListener('pointerup', up);
svg.addEventListener('pointercancel', up);
svg.addEventListener('pointerleave', () => setHot(-1));

svg.addEventListener('keydown', (e) => {
  const k = e.key;
  const snap = Math.floor(minute / 10) * 10;
  if (k === 'ArrowRight' || k === 'ArrowUp') setMinute(snap + 10, true);
  else if (k === 'ArrowLeft' || k === 'ArrowDown') setMinute(snap - 10, true);
  else if (k === 'PageUp') setMinute(snap + 60, true);
  else if (k === 'PageDown') setMinute(snap - 60, true);
  else if (k === 'Home') setMinute(0, true);
  else if (k === 'End') setMinute(1430, true);
  else if (k === ' ' || k === 'Enter') { setPlaying(!playing); }
