// entry: petals bloom up to the current time in a quick clockwise wave
gBars.classList.add('is-reset');
setMinute(minute, false);
setPlaying(playing);
setTimeout(() => { if (root.isConnected) gBars.classList.remove('is-reset'); }, 1200);
